INSERT INTO canonical_pod_scenarios SELECT * FROM json_populate_recordset(null::canonical_pod_scenarios, $m$
[{"id":"method-pod-43-scene:SC01-S01","pod_slug":"method-pod-43-scene","scene_number":1,"scene_label":"Scene 1","scene_title":"Il palazzo in mezzo al campo","scene_subtitle":"joint construction","difficulty":null,"sentence_number":1,"global_order":1,"speaker":"TOM","english_text":"It's not that you know the words. You know what's between the words. The edges. Like a city — you don't know a city because you know the buildings; you know it because you know the streets. So a new word without streets…","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non è che conosci le parole. Conosci quello che c'è tra le parole. I collegamenti. Come una città — non conosci una città perché conosci i palazzi; la conosci perché conosci le strade. Quindi una parola nuova senza strade…","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC01-S02","pod_slug":"method-pod-43-scene","scene_number":1,"scene_label":"Scene 1","scene_title":"Il palazzo in mezzo al campo","scene_subtitle":"joint construction","difficulty":null,"sentence_number":2,"global_order":2,"speaker":"ARAN","english_text":"…is a building in the middle of a field.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…è un palazzo in mezzo a un campo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC01-S03","pod_slug":"method-pod-43-scene","scene_number":1,"scene_label":"Scene 1","scene_title":"Il palazzo in mezzo al campo","scene_subtitle":"joint construction","difficulty":null,"sentence_number":3,"global_order":3,"speaker":"TOM","english_text":"Exactly that.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Esatto, proprio così.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC01-S04","pod_slug":"method-pod-43-scene","scene_number":1,"scene_label":"Scene 1","scene_title":"Il palazzo in mezzo al campo","scene_subtitle":"joint construction","difficulty":null,"sentence_number":4,"global_order":4,"speaker":"ARAN","english_text":"Nobody lives there. And schools keep building them. Poor things.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non ci abita nessuno. E le scuole continuano a costruirli. Poverini.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S01","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":1,"global_order":5,"speaker":"ARAN","english_text":"I've got a story. It proves nothing — accept it anyway.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ho una storia. Non dimostra niente — accettala lo stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S02","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":2,"global_order":6,"speaker":"TOM","english_text":"Go on.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-09-03T23:24:13.983302+00:00","variant_key":null,"target_text":"Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S03","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":3,"global_order":7,"speaker":"ARAN","english_text":"A learner writes to me: the words she remembers are the ones that cost her effort. The easy ones, the ones that came free — gone. Every single one.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Una studentessa mi scrive: le parole che ricorda sono quelle che le sono costate fatica. Quelle facili, quelle venute gratis — sparite. Tutte quante.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S04","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":4,"global_order":8,"speaker":"TOM","english_text":"One learner. You're building a church on one learner?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Una studentessa. Stai costruendo una chiesa su una studentessa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S05","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":5,"global_order":9,"speaker":"ARAN","english_text":"I said it proves nothing. But you'll remember it, won't you?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ho detto che non dimostra niente. Ma tu te la ricorderai, no?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC02-S06","pod_slug":"method-pod-43-scene","scene_number":2,"scene_label":"Scene 2","scene_title":"Il colpo basso","scene_subtitle":"anecdote-with-flag, challenged","difficulty":null,"sentence_number":6,"global_order":10,"speaker":"TOM","english_text":"…That's a dirty trick. Yes.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Che colpo basso. Sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S01","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":1,"global_order":11,"speaker":"TOM","english_text":"Can we try again? More slowly.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Possiamo riprovare? Più lentamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S02","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":2,"global_order":12,"speaker":"ARAN","english_text":"Of course.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Certo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S03","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":3,"global_order":13,"speaker":"TOM","english_text":"I don't need all the words. I need three. Three words. No — two. Two words, and I can talk all day.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non mi servono tutte le parole. Me ne servono tre. Tre parole. No — due. Due parole, e posso parlare tutto il giorno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S04","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":4,"global_order":14,"speaker":"ARAN","english_text":"You said three.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Hai detto tre.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S05","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":5,"global_order":15,"speaker":"TOM","english_text":"The third one is you.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"La terza sei tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC03-S06","pod_slug":"method-pod-43-scene","scene_number":3,"scene_label":"Scene 3","scene_title":"Due parole","scene_subtitle":"ZERO-ADMISSION — public self-repair, teasing audit","difficulty":null,"sentence_number":6,"global_order":16,"speaker":"ARAN","english_text":"Very well. That's enough for me.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Benissimo. A me basta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S01","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":1,"global_order":17,"speaker":"ARAN","english_text":"The moment you've got edges, you can go in lots of directions. And that's when it becomes a game.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Nel momento in cui hai i collegamenti, puoi andare in tante direzioni. Ed è lì che diventa un gioco.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S02","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":2,"global_order":18,"speaker":"TOM","english_text":"So what you're saying is: control arrives before correctness.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi quello che stai dicendo è: il controllo arriva prima della correttezza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S03","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":3,"global_order":19,"speaker":"ARAN","english_text":"Hang on — that makes me think of the garden. Two minutes, I promise.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Aspetta — questo mi fa pensare al giardino. Due minuti, promesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S04","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":4,"global_order":20,"speaker":"TOM","english_text":"Clock's running.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Il tempo corre.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S05","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":5,"global_order":21,"speaker":"ARAN","english_text":"Nobody designs a garden leaf by leaf. Nobody can. You plant, and the garden answers, and then you find out what you've actually got, which is never the thing you drew. That's a garden, not a lesson plan. Anyway — where were we?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Nessuno progetta un giardino foglia per foglia. Nessuno ci riesce. Tu pianti, e il giardino risponde, e poi scopri quello che hai davvero, che non è mai quello che avevi disegnato. Quello è un giardino, non un piano di lezione. Comunque — dov'eravamo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC04-S06","pod_slug":"method-pod-43-scene","scene_number":4,"scene_label":"Scene 4","scene_title":"Dov'eravamo?","scene_subtitle":"reformulation, flagged digression and return","difficulty":null,"sentence_number":6,"global_order":22,"speaker":"TOM","english_text":"Control before correctness. And your garden just agreed with me.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Al controllo prima della correttezza. E il tuo giardino mi ha appena dato ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S01","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":1,"global_order":23,"speaker":"ARAN","english_text":"Is this a good idea, or a bad idea?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È una buona idea, o una cattiva idea?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S02","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":2,"global_order":24,"speaker":"TOM","english_text":"I don't know.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non lo so.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S03","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":3,"global_order":25,"speaker":"ARAN","english_text":"You don't know?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non lo sai?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S04","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":4,"global_order":26,"speaker":"TOM","english_text":"No. I don't know, and you don't know. Is it a good idea? I don't know. Is it a bad idea? I don't know. And you don't know.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No. Io non lo so, e tu non lo sai. È una buona idea? Non lo so. È una cattiva idea? Non lo so. E tu non lo sai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S05","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":5,"global_order":27,"speaker":"ARAN","english_text":"You're right. I don't know.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Hai ragione. Non lo so.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC05-S06","pod_slug":"method-pod-43-scene","scene_number":5,"scene_label":"Scene 5","scene_title":"Non lo so","scene_subtitle":"ZERO-ADMISSION — not-knowing held with status","difficulty":null,"sentence_number":6,"global_order":28,"speaker":"TOM","english_text":"Good. Now we can start to think. What do you think?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Bene. Adesso possiamo iniziare a pensare. Tu cosa pensi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S01","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":1,"global_order":29,"speaker":"TOM","english_text":"How much time is it going to take?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quanto tempo ci vorrà?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S02","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":2,"global_order":30,"speaker":"ARAN","english_text":"A lot.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tanto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S03","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":3,"global_order":31,"speaker":"TOM","english_text":"How much? Ten hours?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quanto? Dieci ore?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S04","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":4,"global_order":32,"speaker":"ARAN","english_text":"More. Ten hours — and then ten more.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Di più. Dieci ore — e poi altre dieci.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S05","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":5,"global_order":33,"speaker":"TOM","english_text":"And then?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E poi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S06","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":6,"global_order":34,"speaker":"ARAN","english_text":"And then ten more. And then ten more.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E poi altre dieci. E poi altre dieci.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S07","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":7,"global_order":35,"speaker":"TOM","english_text":"So how much altogether? A hundred?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi quanto in tutto? Cento?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC06-S08","pod_slug":"method-pod-43-scene","scene_number":6,"scene_label":"Scene 6","scene_title":"Cento ore","scene_subtitle":"ZERO-ADMISSION — the precision haggle","difficulty":null,"sentence_number":8,"global_order":36,"speaker":"ARAN","english_text":"A hundred hours. It's a hundred hours. Ten hours, and then ten more, and then ten more — a hundred hours. Take them as you want.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Cento ore. Sono cento ore. Dieci ore, e poi altre dieci, e poi altre dieci — cento ore. Prendile come vuoi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S01","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":1,"global_order":37,"speaker":"TOM","english_text":"Schools. How would you do it in a school?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Le scuole. Come lo faresti in una scuola?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S02","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":2,"global_order":38,"speaker":"ARAN","english_text":"It's been a long time since I've worked in schools. I'm out of practice, and I haven't thought about it much.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È da tanto tempo che non lavoro nelle scuole. Sono fuori allenamento, e non ci ho pensato molto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S03","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":3,"global_order":39,"speaker":"TOM","english_text":"But?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Però?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S04","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":4,"global_order":40,"speaker":"ARAN","english_text":"But if you give me one roll of the dice — one day a week. One whole day, every week, for a year. That's what I'd want to test, and I'd bet on it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Però se mi dai un solo tiro di dadi — un giorno alla settimana. Un giorno intero, ogni settimana, per un anno. È quello che vorrei provare, e ci scommetterei.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S05","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":5,"global_order":41,"speaker":"TOM","english_text":"That's a big bite out of the timetable.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È un bel morso all'orario.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC07-S06","pod_slug":"method-pod-43-scene","scene_number":7,"scene_label":"Scene 7","scene_title":"Un tiro di dadi","scene_subtitle":"the flagged guess","difficulty":null,"sentence_number":6,"global_order":42,"speaker":"ARAN","english_text":"It looks big. But I suspect you wouldn't even need the whole year.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sembra grande. Ma sospetto che non servirebbe nemmeno l'anno intero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S01","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":1,"global_order":43,"speaker":"TOM","english_text":"So the rules of grammar — where do they live, in the head?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi le regole della grammatica — dove stanno, nella testa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S02","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":2,"global_order":44,"speaker":"ARAN","english_text":"Ask the question at the level of neurons. How would it even work?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Fai la domanda al livello dei neuroni. Come funzionerebbe, anche solo in teoria?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S03","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":3,"global_order":45,"speaker":"TOM","english_text":"A parallel system? Word types, categories, a machine for putting them in order, and another machine to check the first one, and somewhere to keep all of that, and a way to learn it as a child…","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Un sistema parallelo? Tipi di parole, categorie, una macchina per metterle in ordine, e un'altra macchina che controlla la prima, e un posto dove tenere tutto questo, e un modo per impararlo da bambino…","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S04","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":4,"global_order":46,"speaker":"ARAN","english_text":"Listen to yourself. It gets complicated very fast.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ascoltati. Diventa complicato molto in fretta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S05","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":5,"global_order":47,"speaker":"TOM","english_text":"And so?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E quindi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC08-S06","pod_slug":"method-pod-43-scene","scene_number":8,"scene_label":"Scene 8","scene_title":"Troppo complicato","scene_subtitle":"the razor","difficulty":null,"sentence_number":6,"global_order":48,"speaker":"ARAN","english_text":"It's complicated — so it can't be a thing. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È complicato — quindi non può essere una cosa vera. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S01","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":1,"global_order":49,"speaker":"TOM","english_text":"A few years ago we had a group — brilliant people. We wanted to grow food for the whole street.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Qualche anno fa avevamo un gruppo — gente in gamba. Volevamo coltivare cibo per tutta la via.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S02","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":2,"global_order":50,"speaker":"ARAN","english_text":"Sounds fantastic. And what happened to that group?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sembra fantastico. E che fine ha fatto, quel gruppo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S03","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":3,"global_order":51,"speaker":"TOM","english_text":"…It's gone cold.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Si è raffreddato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S04","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":4,"global_order":52,"speaker":"ARAN","english_text":"How many of you were there?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quanti eravate?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S05","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":5,"global_order":53,"speaker":"TOM","english_text":"Fifteen. We did a design day, we made a ten-year plan. All of them busy. All of them time-poor.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindici. Abbiamo fatto una giornata di progettazione, abbiamo fatto un piano di dieci anni. Tutti impegnati. Tutti poveri di tempo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC09-S06","pod_slug":"method-pod-43-scene","scene_number":9,"scene_label":"Scene 9","scene_title":"Che fine ha fatto?","scene_subtitle":"the audit inside the glow","difficulty":null,"sentence_number":6,"global_order":54,"speaker":"ARAN","english_text":"There's your answer. Fifteen people in a whole street, and every one of them without time. It wasn't the idea that failed — there just aren't many people with time. There never are, anywhere.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ecco la risposta. Quindici persone in tutta una via, e nessuna di loro con tempo. Non è stata l'idea a fallire — è che non c'è tanta gente che ha tempo. Non c'è mai, da nessuna parte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC10-S01","pod_slug":"method-pod-43-scene","scene_number":10,"scene_label":"Scene 10","scene_title":"Ci sbagliavamo","scene_subtitle":"public position-abandonment","difficulty":null,"sentence_number":1,"global_order":55,"speaker":"ARAN","english_text":"For years we said it: three words of a language, an empty gesture. Classic tokenism. We used to laugh about it, honestly. And we were utterly wrong.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Per anni l'abbiamo detto: tre parole di una lingua, un gesto vuoto. Tokenismo classico. Ci ridevamo sopra, sinceramente. E ci sbagliavamo completamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC10-S02","pod_slug":"method-pod-43-scene","scene_number":10,"scene_label":"Scene 10","scene_title":"Ci sbagliavamo","scene_subtitle":"public position-abandonment","difficulty":null,"sentence_number":2,"global_order":56,"speaker":"TOM","english_text":"Completely wrong?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Completamente?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC10-S03","pod_slug":"method-pod-43-scene","scene_number":10,"scene_label":"Scene 10","scene_title":"Ci sbagliavamo","scene_subtitle":"public position-abandonment","difficulty":null,"sentence_number":3,"global_order":57,"speaker":"ARAN","english_text":"Utterly. Every single one of those people — three words, said with effort, badly, in the wrong order — made a connection that wouldn't have been there otherwise, and they didn't have to learn anything else at all. Three words open a door, and the door stays open.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Completamente. Ognuna di quelle persone — tre parole, dette con fatica, male, nell'ordine sbagliato — ha creato un legame che altrimenti non ci sarebbe stato, e non hanno dovuto imparare nient'altro. Tre parole aprono una porta, e la porta resta aperta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC10-S04","pod_slug":"method-pod-43-scene","scene_number":10,"scene_label":"Scene 10","scene_title":"Ci sbagliavamo","scene_subtitle":"public position-abandonment","difficulty":null,"sentence_number":4,"global_order":58,"speaker":"TOM","english_text":"And they cost the person almost nothing. That still amazes me.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E alla persona non costano quasi niente. Questo mi stupisce ancora.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S01","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":1,"global_order":59,"speaker":"TOM","english_text":"You waited sixteen months to test one word? You're mad.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Hai aspettato sedici mesi per testare una parola? Sei matto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S02","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":2,"global_order":60,"speaker":"ARAN","english_text":"Sixteen months, yes. And since you've just called me mad —","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sedici mesi, sì. E visto che mi hai appena dato del matto —","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S03","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":3,"global_order":61,"speaker":"TOM","english_text":"Oh no.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Oh no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S04","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":4,"global_order":62,"speaker":"ARAN","english_text":"— you tested yourself in Chinese for a whole day. For fun. Nobody asked you to. You told me about it afterwards, and you were proud of it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"— tu ti sei messo alla prova in cinese per un giorno intero. Per divertimento. Nessuno te l'aveva chiesto. Me l'hai raccontato dopo, ed eri pure fiero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S05","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":5,"global_order":63,"speaker":"TOM","english_text":"…No, you're completely right.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…No, hai perfettamente ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC11-S06","pod_slug":"method-pod-43-scene","scene_number":11,"scene_label":"Scene 11","scene_title":"Sedici mesi","scene_subtitle":"the mirrored tease","difficulty":null,"sentence_number":6,"global_order":64,"speaker":"ARAN","english_text":"Mad, both of us. That's why it works.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Matti, tutti e due. È per questo che funziona.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S01","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":1,"global_order":65,"speaker":"TOM","english_text":"Learning with other people — it's not a course. It's flexible; you decide together where you're going; it's temporary; and at the end, the thing you've made lives between you and the road. It's not a course. It's a trip in—","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Imparare con altre persone — non è un corso. È flessibile; decidete insieme dove andare; è temporaneo; e alla fine, quello che avete creato vive tra voi e la strada. Non è un corso. È un viaggio in—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S02","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":2,"global_order":66,"speaker":"ARAN","english_text":"—a car. Yes. I like the road trip. And it goes wider than that.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"—macchina. Sì. Mi piace, il viaggio in macchina. E va anche più in là.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S03","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":3,"global_order":67,"speaker":"TOM","english_text":"Wider how?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Più in là come?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S04","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":4,"global_order":68,"speaker":"ARAN","english_text":"You'll do more than one. Sometimes with the same people, sometimes with new ones. A tour. And there will be crashes — that's the part you actually learn from.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ne farai più di uno. A volte con le stesse persone, a volte con gente nuova. Un tour. E ci saranno degli incidenti — ed è da lì che impari davvero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S05","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":5,"global_order":69,"speaker":"TOM","english_text":"Now you're driving my metaphor.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Adesso la mia metafora la stai guidando tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC12-S06","pod_slug":"method-pod-43-scene","scene_number":12,"scene_label":"Scene 12","scene_title":"Le chiavi","scene_subtitle":"the metaphor handover","difficulty":null,"sentence_number":6,"global_order":70,"speaker":"ARAN","english_text":"You gave me the keys.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Mi hai dato tu le chiavi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S01","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":1,"global_order":71,"speaker":"TOM","english_text":"Careful with that partner. You might wake up in bed with a crocodile.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Attento con quel socio. Potresti svegliarti nel letto con un coccodrillo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S02","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":2,"global_order":72,"speaker":"ARAN","english_text":"The crocodile — we're still using it? After all these years?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Il coccodrillo — lo usiamo ancora? Dopo tutti questi anni?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S03","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":3,"global_order":73,"speaker":"TOM","english_text":"It's your line, not mine. You said it first, years ago, in the middle of something else entirely, and you said it exactly like this: I lost my foot in that river—","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È una battuta tua, non mia. L'hai detta tu per primo, anni fa, nel mezzo di tutt'altro discorso, e l'hai detta proprio così: ho perso il piede in quel fiume—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S04","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":4,"global_order":74,"speaker":"ARAN","english_text":"—please accept my anecdotal evidence. Yes. Though by now it's yours too.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"— ti prego, accetta la mia prova aneddotica. Sì. Anche se ormai è anche tua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S05","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":5,"global_order":75,"speaker":"TOM","english_text":"It is now.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Adesso sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC13-S06","pod_slug":"method-pod-43-scene","scene_number":13,"scene_label":"Scene 13","scene_title":"Il coccodrillo","scene_subtitle":"the co-owned line","difficulty":null,"sentence_number":6,"global_order":76,"speaker":"ARAN","english_text":"A good line ends up belonging to both. Like everything else in a long conversation — after a while you stop knowing who brought what.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Una bella battuta finisce per appartenere a tutti e due. Come tutto il resto, in una conversazione lunga — dopo un po' non sai più chi ha portato cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S01","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":1,"global_order":77,"speaker":"ARAN","english_text":"So the third thing — and this is the important one — is that when you actually—","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi la terza cosa — ed è quella importante — è che quando tu davvero—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S02","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":2,"global_order":78,"speaker":"TOM","english_text":"Hang on. The dog.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Aspetta. Il cane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S03","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":3,"global_order":79,"speaker":"ARAN","english_text":"The dog?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Il cane?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S04","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":4,"global_order":80,"speaker":"TOM","english_text":"The dog has opinions. Someone's at the door, and the dog has views about the door, and about the person behind it. This will take a while.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Il cane ha delle opinioni. C'è qualcuno alla porta, e il cane ha le sue idee sulla porta, e su chi c'è dietro. Ci vorrà un po'.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S05","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":5,"global_order":81,"speaker":"ARAN","english_text":"Fine. We'll pick this up next time — you owe me a third thing.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Va bene. Riprendiamo la prossima volta — mi devi una terza cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC14-S06","pod_slug":"method-pod-43-scene","scene_number":14,"scene_label":"Scene 14","scene_title":"Il cane","scene_subtitle":"the banked thread — MINT (container)","difficulty":null,"sentence_number":6,"global_order":82,"speaker":"TOM","english_text":"Noted. The third thing, for next time.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Segnato. La terza cosa, alla prossima.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S01","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":1,"global_order":83,"speaker":"TOM","english_text":"But where does a bank get the money for a mortgage?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ma dove li prende, una banca, i soldi per un mutuo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S02","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":2,"global_order":84,"speaker":"ARAN","english_text":"It doesn't. Watch — I'll be the bank, you be you. You come in, you sit down, and you say it: \"I'd like a mortgage.\" Go on.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-09-03T23:24:14.151448+00:00","variant_key":null,"target_text":"Non li prende. Guarda — io faccio la banca, tu fai te. Tu entri, ti siedi, e dici: «Vorrei un mutuo». Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S03","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":3,"global_order":85,"speaker":"TOM","english_text":"\"I'd like a mortgage.\"","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"«Vorrei un mutuo».","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S04","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":4,"global_order":86,"speaker":"ARAN","english_text":"And the bank says: \"Of course. One moment.\" And it invents the money. There. Now it exists. A second ago it didn't exist, and it didn't come out of anybody else's account.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E la banca dice: «Certo. Un momento». E inventa i soldi. Ecco. Adesso esistono. Un secondo fa non esistevano, e non sono usciti dal conto di nessun altro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S05","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":5,"global_order":87,"speaker":"TOM","english_text":"It doesn't take it from anywhere?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non li prende da nessuna parte?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC15-S06","pod_slug":"method-pod-43-scene","scene_number":15,"scene_label":"Scene 15","scene_title":"Vorrei un mutuo","scene_subtitle":"the puppet show — MINT (the cast partner)","difficulty":null,"sentence_number":6,"global_order":88,"speaker":"ARAN","english_text":"From nowhere. A magic wand. That's why it's a power.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Da nessuna parte. Una bacchetta magica. È per questo che è un potere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S01","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":1,"global_order":89,"speaker":"TOM","english_text":"Thirteen weeks. One full day to start, then two hours a week for eleven weeks, then one full day to close. That would probably be plenty.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tredici settimane. Un giorno pieno per iniziare, poi due ore alla settimana per undici settimane, poi un giorno pieno per chiudere. Probabilmente basterebbe.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S02","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":2,"global_order":90,"speaker":"ARAN","english_text":"Mm. I'd be inclined not to differentiate that much. Here's the model: five days, then a year of an hour or two a week, then five days again. With your thirteen weeks you'd surprise a few people. And you'd lose a few.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Mm. Io sarei propenso a non differenziare così tanto. Il modello è questo: cinque giorni, poi un anno di un'ora o due alla settimana, poi altri cinque giorni. Con le tue tredici settimane qualcuno lo sorprenderesti. E qualcuno lo perderesti.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S03","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":3,"global_order":91,"speaker":"TOM","english_text":"Fewer than you think.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Meno di quanto pensi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S04","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":4,"global_order":92,"speaker":"ARAN","english_text":"Maybe. But one day, twelve weeks, one day — some of them will hear that and think it isn't enough to be worth doing. To me the risk doesn't seem worth it. Five days.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Può darsi. Ma un giorno, dodici settimane, un giorno — qualcuno lo sentirà e penserà che non basta per valerne la pena. A me il rischio non sembra valerne la pena. Cinque giorni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S05","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":5,"global_order":93,"speaker":"TOM","english_text":"And I still like my thirteen weeks.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E a me piacciono ancora le mie tredici settimane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S06","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":6,"global_order":94,"speaker":"ARAN","english_text":"I know. And I still don't.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Lo so. E a me continuano a non piacere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC16-S07","pod_slug":"method-pod-43-scene","scene_number":16,"scene_label":"Scene 16","scene_title":"In pausa","scene_subtitle":"the parked clash — MINT (the park form as summit disagreement)","difficulty":null,"sentence_number":7,"global_order":95,"speaker":"TOM","english_text":"Then we'll put it on pause. Okay.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Allora la mettiamo in pausa. Va bene.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S01","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":1,"global_order":96,"speaker":"TOM","english_text":"I think that when you learn a language you don't need all the words — you need the words you can say something with, and after that you talk, and you talk, and you talk, all day, with people, and after that you have more words, and then—","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Penso che quando impari una lingua non ti servano tutte le parole — ti servono le parole con cui puoi dire qualcosa, e dopo parli, e parli, e parli, tutto il giorno, con la gente, e dopo hai più parole, e poi—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S02","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":2,"global_order":97,"speaker":"ARAN","english_text":"I don't understand.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non ho capito.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S03","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":3,"global_order":98,"speaker":"TOM","english_text":"You don't understand?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non hai capito?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S04","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":4,"global_order":99,"speaker":"ARAN","english_text":"No. Too much. Again — slowly.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No. Troppo. Ancora — lentamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S05","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":5,"global_order":100,"speaker":"TOM","english_text":"You don't need all the words.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non ti servono tutte le parole.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S06","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":6,"global_order":101,"speaker":"ARAN","english_text":"Yes. Now I understand.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sì. Adesso ho capito.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC17-S07","pod_slug":"method-pod-43-scene","scene_number":17,"scene_label":"Scene 17","scene_title":"Non ho capito","scene_subtitle":"ZERO-ADMISSION — MINT — the listener does not understand you","difficulty":null,"sentence_number":7,"global_order":102,"speaker":"TOM","english_text":"Good. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Bene. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S01","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":1,"global_order":103,"speaker":"TOM","english_text":"Are you free on Tuesday?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sei libero martedì?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S02","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":2,"global_order":104,"speaker":"ARAN","english_text":"Tuesday, no. I have something on Tuesday.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Martedì no. Martedì ho un impegno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S03","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":3,"global_order":105,"speaker":"TOM","english_text":"Thursday, then?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Giovedì, allora?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S04","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":4,"global_order":106,"speaker":"ARAN","english_text":"Thursday I'm not here.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Giovedì non ci sono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S05","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":5,"global_order":107,"speaker":"TOM","english_text":"…Tomorrow.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Domani.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S06","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":6,"global_order":108,"speaker":"ARAN","english_text":"Tomorrow?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Domani?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S07","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":7,"global_order":109,"speaker":"TOM","english_text":"Tomorrow. I'll be there at two.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Domani. Sono lì alle due.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC18-S08","pod_slug":"method-pod-43-scene","scene_number":18,"scene_label":"Scene 18","scene_title":"Domani, allora","scene_subtitle":"ZERO-ADMISSION — the arrangement, and the second no","difficulty":null,"sentence_number":8,"global_order":110,"speaker":"ARAN","english_text":"Tomorrow. At two. Four hours going, four hours going home, for two hours of talking with me. …Okay. Tomorrow at two. I'll be here.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Domani. Alle due. Quattro ore per venire, quattro ore per tornare, per due ore di chiacchiere con me. …Va bene. Domani alle due. Io sono qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S01","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":1,"global_order":111,"speaker":"ARAN","english_text":"Day one. Then day two. And after day two — no more. That was all.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Giorno uno. Poi giorno due. E dopo il giorno due — basta. Basta così.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S02","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":2,"global_order":112,"speaker":"TOM","english_text":"For two years.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Per due anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S03","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":3,"global_order":113,"speaker":"ARAN","english_text":"Three. Not two — three years.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tre. Non due — tre anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S04","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":4,"global_order":114,"speaker":"TOM","english_text":"Three years. And it's still there?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tre anni. Ed è ancora lì?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S05","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":5,"global_order":115,"speaker":"ARAN","english_text":"Still there. Not all of it. But I can say it — slowly, today, but I can say it. Day one, day two, three years — and it's still there. That's what I want people to see.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ancora lì. Non tutto. Ma lo so dire — piano, oggi, ma lo so dire. Giorno uno, giorno due, tre anni — ed è ancora lì. È questo che voglio far vedere alla gente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC19-S06","pod_slug":"method-pod-43-scene","scene_number":19,"scene_label":"Scene 19","scene_title":"Tre anni","scene_subtitle":"ZERO-ADMISSION — MINT on 1:396–400 — your read-back was wrong","difficulty":null,"sentence_number":6,"global_order":116,"speaker":"TOM","english_text":"Three years.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tre anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC20-S01","pod_slug":"method-pod-43-scene","scene_number":20,"scene_label":"Scene 20","scene_title":"C'è tanta roba","scene_subtitle":"ZERO-ADMISSION — the stacked commission","difficulty":null,"sentence_number":1,"global_order":117,"speaker":"TOM","english_text":"How did you find it? When? Where? How much time, every day? How often? — There's a lot there.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Come l'hai trovato? Quando? Dove? Quanto tempo, ogni giorno? Quanto spesso? — C'è tanta roba, lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC20-S02","pod_slug":"method-pod-43-scene","scene_number":20,"scene_label":"Scene 20","scene_title":"C'è tanta roba","scene_subtitle":"ZERO-ADMISSION — the stacked commission","difficulty":null,"sentence_number":2,"global_order":118,"speaker":"ARAN","english_text":"Yes.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC20-S03","pod_slug":"method-pod-43-scene","scene_number":20,"scene_label":"Scene 20","scene_title":"C'è tanta roba","scene_subtitle":"ZERO-ADMISSION — the stacked commission","difficulty":null,"sentence_number":3,"global_order":119,"speaker":"TOM","english_text":"There is, isn't there.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Eh, sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC20-S04","pod_slug":"method-pod-43-scene","scene_number":20,"scene_label":"Scene 20","scene_title":"C'è tanta roba","scene_subtitle":"ZERO-ADMISSION — the stacked commission","difficulty":null,"sentence_number":4,"global_order":120,"speaker":"ARAN","english_text":"Yes. A lot. So — first, how. Then when. Then how much, and how often. And after that you can say: but is it good? And I say: I talk. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sì. Tanta. Allora — prima il come. Poi il quando. Poi il quanto, e il quanto spesso. E dopo puoi dire: ma è buono? E io dico: parlo. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC20-S05","pod_slug":"method-pod-43-scene","scene_number":20,"scene_label":"Scene 20","scene_title":"C'è tanta roba","scene_subtitle":"ZERO-ADMISSION — the stacked commission","difficulty":null,"sentence_number":5,"global_order":121,"speaker":"TOM","english_text":"Start with how.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Comincia dal come.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S01","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":1,"global_order":122,"speaker":"ARAN","english_text":"Fish, in Welsh: pysgod. Now, if I just make you say it — pysgod, pysgod, pysgod — you're not making a memory. It's too easy.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Pesce, in gallese: pysgod. Ora, se ti faccio solo ripetere — pysgod, pysgod, pysgod — non stai formando una memoria. È troppo facile.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S02","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":2,"global_order":123,"speaker":"TOM","english_text":"Pysgod. …Actually I've half got it already. \"Pys\" — a bit like puss, the cat. And \"cod\" is a fish. Pysgod.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Pysgod. …In realtà l'ho già mezzo preso. «Pys» — un po' come puss, il gatto. E «cod» è un pesce. Pysgod.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S03","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":3,"global_order":124,"speaker":"ARAN","english_text":"There. Look at what you just did. I didn't ask you for that. You went looking for a hook, on your own, and the hook cost you something — and that's the memory, not the word. Now: if we leave it there, and in two hours I come back and ask you the Welsh for fish, it'll be hard. And the hard is the point.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ecco. Guarda cos'hai appena fatto. Non te l'avevo chiesto. Sei andato a cercarti un gancio, da solo, e il gancio ti è costato qualcosa — e la memoria è quella, non la parola. Ora: se lo lasciamo lì, e tra due ore torno e ti chiedo il gallese per pesce, sarà difficile. E il difficile è il punto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S04","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":4,"global_order":125,"speaker":"TOM","english_text":"So you're going to leave it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi lo lasci lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S05","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":5,"global_order":126,"speaker":"ARAN","english_text":"I'm going to leave it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Lo lascio lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S06","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":6,"global_order":127,"speaker":"TOM","english_text":"Pysgod.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Pysgod.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC21-S07","pod_slug":"method-pod-43-scene","scene_number":21,"scene_label":"Scene 21","scene_title":"Pysgod","scene_subtitle":"the specimen","difficulty":null,"sentence_number":7,"global_order":128,"speaker":"ARAN","english_text":"Stop that.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Smettila.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S01","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":1,"global_order":129,"speaker":"TOM","english_text":"Wait. How do we know that?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Aspetta. Come lo sappiamo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S02","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":2,"global_order":130,"speaker":"ARAN","english_text":"Know what?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Come sappiamo cosa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S03","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":3,"global_order":131,"speaker":"TOM","english_text":"That it's effort that makes the memory. I feel it's true. It seems to work. But where are we, actually — is it in the studies, peer-reviewed, mapped out, can we say \"proven scientific fact\"? Or is it one man in California with a good idea, and us with a feeling?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Che è la fatica a fare la memoria. Io sento che è vero. Sembra funzionare. Ma a che punto siamo, davvero — è negli studi, con la peer review, tutto mappato, possiamo dire «fatto scientifico dimostrato»? O è un signore in California con una buona idea, e noi con una sensazione?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S04","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":4,"global_order":132,"speaker":"ARAN","english_text":"…It's closer to the man in California. Bjork says it, and he's careful, and the work is good. Proven, in the sense you mean? No. What I've got on top of that is me — one person, testing on himself for years. That's not proof, that's a story with a flag on it. But the question you just asked is the right one, and nobody in this field asks it enough. So — no. We don't know. We think.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…È più vicino al signore in California. Lo dice Bjork, ed è uno attento, e il lavoro è buono. Dimostrato, nel senso che intendi tu? No. Quello che ho in più è me stesso — una persona, che si testa da sola da anni. Non è una prova, è una storia con una bandierina sopra. Ma la domanda che hai appena fatto è quella giusta, e in questo campo nessuno la fa abbastanza. Quindi — no. Non lo sappiamo. Lo pensiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S05","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":5,"global_order":133,"speaker":"TOM","english_text":"\"We think\" I can live with.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Con «lo pensiamo» posso convivere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC22-S06","pod_slug":"method-pod-43-scene","scene_number":22,"scene_label":"Scene 22","scene_title":"Come lo sappiamo?","scene_subtitle":"the premise audit, received as a gift","difficulty":null,"sentence_number":6,"global_order":134,"speaker":"ARAN","english_text":"\"We think\" is where every good thing starts.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"«Lo pensiamo» è da dove parte ogni cosa buona.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S01","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":1,"global_order":135,"speaker":"TOM","english_text":"But before they press play, you have to work out what they want. Their goals.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ma prima che premano play devi capire cosa vogliono. I loro obiettivi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S02","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":2,"global_order":136,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S03","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":3,"global_order":137,"speaker":"TOM","english_text":"No?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S04","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":4,"global_order":138,"speaker":"ARAN","english_text":"No. They press play. That's it. What we do is notice when they stop. They come back after a month — we noticed. So we put a few of the early sentences back in front of them. They come back the next day — we just carry on. Nobody fills in a form. Nobody has a goal. They press play, and the thing that's paying attention is us, not them.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No. Premono play. Basta. Quello che facciamo noi è accorgerci quando si fermano. Tornano dopo un mese — ce ne siamo accorti. Allora gli rimettiamo davanti qualche frase delle prime. Tornano il giorno dopo — andiamo avanti e basta. Nessuno compila un modulo. Nessuno ha un obiettivo. Premono play, e la cosa che sta attenta siamo noi, non loro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S05","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":5,"global_order":139,"speaker":"TOM","english_text":"…Okay. No form.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Va bene. Niente modulo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC23-S06","pod_slug":"method-pod-43-scene","scene_number":23,"scene_label":"Scene 23","scene_title":"Premi play","scene_subtitle":"the premise refused","difficulty":null,"sentence_number":6,"global_order":140,"speaker":"ARAN","english_text":"No form. Press play.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Niente modulo. Premi play.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S01","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":1,"global_order":141,"speaker":"TOM","english_text":"There's a school that wants you. Five days, a group of twelve. Will you do it?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"C'è una scuola che ti vuole. Cinque giorni, un gruppo di dodici. Lo fai?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S02","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":2,"global_order":142,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S03","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":3,"global_order":143,"speaker":"TOM","english_text":"No?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S04","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":4,"global_order":144,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S05","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":5,"global_order":145,"speaker":"TOM","english_text":"Not even for a week? They're keen. They'd pay properly.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Nemmeno per una settimana? Ci tengono. Pagano bene.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S06","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":6,"global_order":146,"speaker":"ARAN","english_text":"No. One to one. That's all I say yes to now.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"No. Uno a uno. È l'unica cosa a cui dico di sì, ormai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S07","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":7,"global_order":147,"speaker":"TOM","english_text":"Since when?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Da quando?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S08","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":8,"global_order":148,"speaker":"ARAN","english_text":"Since I understood what a group can do to a week. One to one, I know it works — whoever they are, whatever the room, we get there. A group — four people in a bed and breakfast for five days, one of them has two bad days, and all of it lands on the other three. I'd need to know who's in the room before I said yes, and I never do. So: no.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Da quando ho capito cosa può fare un gruppo a una settimana. Uno a uno, so che funziona — chiunque sia, qualunque sia la stanza, ci arriviamo. Un gruppo — quattro persone in un bed and breakfast per cinque giorni, uno di loro ha due giornate storte, e tutto cade addosso agli altri tre. Dovrei sapere chi c'è nella stanza prima di dire sì, e non lo so mai. Quindi: no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S09","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":9,"global_order":149,"speaker":"TOM","english_text":"…I'll tell them no.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Gli dico di no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC24-S10","pod_slug":"method-pod-43-scene","scene_number":24,"scene_label":"Scene 24","scene_title":"Solo uno a uno","scene_subtitle":"MINT on 2:170–172 — the bare no","difficulty":null,"sentence_number":10,"global_order":150,"speaker":"ARAN","english_text":"Tell them one to one. Then yes.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Digli uno a uno. Allora sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S01","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":1,"global_order":151,"speaker":"TOM","english_text":"Every teacher on earth says the same thing. \"I'm intermediate — how do I get to fluent?\" \"Practise. Go and use it. Listen to the radio, talk to people.\"","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tutti gli insegnanti del mondo dicono la stessa cosa. «Sono a un livello intermedio — come arrivo a parlare bene?» «Fai pratica. Vai e usala. Ascolta la radio, parla con la gente.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S02","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":2,"global_order":152,"speaker":"ARAN","english_text":"And that's true.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ed è vero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S03","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":3,"global_order":153,"speaker":"TOM","english_text":"Is it?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Davvero?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S04","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":4,"global_order":154,"speaker":"ARAN","english_text":"That's true, that's right, that's exactly what you have to do — and it's incredibly painful if nobody has prepared you for it. If all you've got is a pile of words and a rule book, you walk into that room and have to invent every sentence on the spot, live. That's the cliff. But if you've already walked a thousand little paths through the words you've got, the room isn't a cliff any more. It's just more of the same.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È vero, è giusto, è esattamente quello che devi fare — ed è incredibilmente doloroso se nessuno ti ci ha preparato. Se tutto quello che hai è un mucchio di parole e un libro di regole, entri in quella stanza e devi inventarti ogni frase lì per lì, dal vivo. Quello è il precipizio. Ma se hai già percorso mille piccoli sentieri tra le parole che hai, la stanza non è più un precipizio. È solo altro dello stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S05","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":5,"global_order":155,"speaker":"TOM","english_text":"So \"go and practise\" is right, and it's the cruellest thing you can say.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi «vai a far pratica» è giusto, ed è la cosa più crudele che puoi dire.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC25-S06","pod_slug":"method-pod-43-scene","scene_number":25,"scene_label":"Scene 25","scene_title":"È vero, ma","scene_subtitle":"concession-then-build","difficulty":null,"sentence_number":6,"global_order":156,"speaker":"ARAN","english_text":"Both. At the same time.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tutte e due. Nello stesso momento.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC26-S01","pod_slug":"method-pod-43-scene","scene_number":26,"scene_label":"Scene 26","scene_title":"Rosso, ma","scene_subtitle":"ZERO-ADMISSION — the counterexample absorbed","difficulty":null,"sentence_number":1,"global_order":157,"speaker":"ARAN","english_text":"After \"red\", what can I say? \"Red bus.\" \"A red house.\" \"One that's red.\" A lot. And what can't I say? I can't say \"red but\".","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Dopo «rosso», cosa posso dire? «Autobus rosso.» «Una casa rossa.» «Uno rosso.» Tanto. E cosa non posso dire? Non posso dire «rosso ma».","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC26-S02","pod_slug":"method-pod-43-scene","scene_number":26,"scene_label":"Scene 26","scene_title":"Rosso, ma","scene_subtitle":"ZERO-ADMISSION — the counterexample absorbed","difficulty":null,"sentence_number":2,"global_order":158,"speaker":"TOM","english_text":"\"I'd like one that's red — but I don't mind.\"","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"«Vorrei uno rosso — ma non importa.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC26-S03","pod_slug":"method-pod-43-scene","scene_number":26,"scene_label":"Scene 26","scene_title":"Rosso, ma","scene_subtitle":"ZERO-ADMISSION — the counterexample absorbed","difficulty":null,"sentence_number":3,"global_order":159,"speaker":"ARAN","english_text":"…You can. I said you can't, and you can. Good. So after \"red\" there is a \"but\" — with a little something in it. Now I know one more. So do you.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Puoi. Ho detto che non puoi, e puoi. Bene. Quindi dopo «rosso» c'è un «ma» — con qualcosina in mezzo. Adesso ne so una in più. Anche tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC26-S04","pod_slug":"method-pod-43-scene","scene_number":26,"scene_label":"Scene 26","scene_title":"Rosso, ma","scene_subtitle":"ZERO-ADMISSION — the counterexample absorbed","difficulty":null,"sentence_number":4,"global_order":160,"speaker":"TOM","english_text":"A small one.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Piccola, però.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC26-S05","pod_slug":"method-pod-43-scene","scene_number":26,"scene_label":"Scene 26","scene_title":"Rosso, ma","scene_subtitle":"ZERO-ADMISSION — the counterexample absorbed","difficulty":null,"sentence_number":5,"global_order":161,"speaker":"ARAN","english_text":"All of it is small. That's the language.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È tutto piccolo. È la lingua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S01","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":1,"global_order":162,"speaker":"TOM","english_text":"So what you're saying is: the films are in the language they're learning, with subtitles.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quindi quello che stai dicendo è: i film sono nella lingua che stanno imparando, con i sottotitoli.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S02","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":2,"global_order":163,"speaker":"ARAN","english_text":"Nearly. Not subtitles.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Quasi. Non i sottotitoli.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S03","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":3,"global_order":164,"speaker":"TOM","english_text":"What, then?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E cosa, allora?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S04","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":4,"global_order":165,"speaker":"ARAN","english_text":"Transcripts. That's not a small difference, it's the whole thing. Subtitles put the words on the screen while you're listening, so your eyes do the work and your ears go to sleep — and that's the wrong solution and it won't work. A transcript you read before. Then you listen without it, and now your ears have a ladder. Same film, completely different act.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Le trascrizioni. Non è una differenza piccola, è tutta la faccenda. I sottotitoli ti mettono le parole sullo schermo mentre ascolti, così il lavoro lo fanno gli occhi e le orecchie si addormentano — ed è la soluzione sbagliata, e non funziona. Una trascrizione la leggi prima. Poi ascolti senza, e adesso le orecchie hanno una scala. Stesso film, atto completamente diverso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S05","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":5,"global_order":166,"speaker":"TOM","english_text":"…Okay. So I was thinking: films for learners, with the words on the screen. You're thinking: films for everyone, and a ladder up to them for the learners.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…Va bene. Io pensavo: film per chi impara, con le parole sullo schermo. Tu pensi: film per tutti, e una scala per arrivarci, per chi impara.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC27-S06","pod_slug":"method-pod-43-scene","scene_number":27,"scene_label":"Scene 27","scene_title":"Non è quello che dico","scene_subtitle":"the misreading corrected","difficulty":null,"sentence_number":6,"global_order":167,"speaker":"ARAN","english_text":"That's it. Now you've got it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ecco. Adesso ci sei.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S01","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":1,"global_order":168,"speaker":"ARAN","english_text":"There's a researcher — Wray, formulaic language, very highly regarded — and for a few years she's been saying, in conversation, I don't think she's published it: there is no such thing as a word.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"C'è una ricercatrice — Wray, linguaggio formulaico, molto stimata — e da qualche anno dice, in conversazione, non credo l'abbia pubblicato: le parole non esistono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S02","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":2,"global_order":169,"speaker":"TOM","english_text":"No such thing.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non esistono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S03","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":3,"global_order":170,"speaker":"ARAN","english_text":"There aren't any. We use the word \"word\" for something that doesn't really exist and isn't a helpful way of cutting things up. And every time I've heard her say it I've thought: I can't keep up with this, my brain already hurts. And she's right, and I still can't keep up.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non ce ne sono. Usiamo la parola «parola» per una cosa che in realtà non esiste, e che non è un modo utile di tagliare le cose. E ogni volta che gliel'ho sentito dire ho pensato: non ce la faccio a starle dietro, mi fa già male il cervello. E ha ragione, e continuo a non starle dietro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S04","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":4,"global_order":171,"speaker":"TOM","english_text":"She'd allow a syllable. A sound. Things that start and stop.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Una sillaba la concederebbe. Un suono. Cose che iniziano e finiscono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S05","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":5,"global_order":172,"speaker":"ARAN","english_text":"Yes. So — we'd all say \"to boldly go\" is three words. And by most of the ways you could actually define a word, it's one. And then you're into woo.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sì. Allora — diremmo tutti che «to boldly go» sono tre parole. E per quasi tutti i modi in cui potresti davvero definire una parola, è una. E poi finisci nel woo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S06","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":6,"global_order":173,"speaker":"TOM","english_text":"It's one unit of meaning. That's all it is.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È un'unità di significato. Tutto lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC28-S07","pod_slug":"method-pod-43-scene","scene_number":28,"scene_label":"Scene 28","scene_title":"Non esistono le parole","scene_subtitle":"the reported claim too big to hold","difficulty":null,"sentence_number":7,"global_order":174,"speaker":"ARAN","english_text":"That's all it is. And that's the woo.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Tutto lì. Ed è quello il woo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S01","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":1,"global_order":175,"speaker":"TOM","english_text":"Ebbinghaus. The German. One man, memorising lists of nonsense syllables, testing himself, sample size one, corroborated by nobody — and a hundred years later everyone still quotes his intervals as if they were physics. And yet the practice works. There's truth in the practice without any consistency about the why.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ebbinghaus. Il tedesco. Un uomo solo, che impara a memoria liste di sillabe senza senso, si testa da solo, campione di uno, confermato da nessuno — e cent'anni dopo tutti citano ancora i suoi intervalli come se fossero fisica. Eppure la pratica funziona. C'è del vero nella pratica, senza nessuna coerenza sul perché.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S02","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":2,"global_order":176,"speaker":"ARAN","english_text":"That's exactly where I was about to go.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"È esattamente lì che stavo per andare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S03","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":3,"global_order":177,"speaker":"TOM","english_text":"Was it?","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Davvero?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S04","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":4,"global_order":178,"speaker":"ARAN","english_text":"Word for word. I'd lost his name, but that's the turn. So take it — you're already there.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Parola per parola. Mi era sfuggito il nome, ma la svolta è quella. Quindi prenditela — ci sei già.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S05","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":5,"global_order":179,"speaker":"TOM","english_text":"Then I'll take it. The why is the interesting bit, and nobody's got it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Allora me la prendo. Il perché è la parte interessante, e non ce l'ha nessuno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC29-S06","pod_slug":"method-pod-43-scene","scene_number":29,"scene_label":"Scene 29","scene_title":"Proprio lì","scene_subtitle":"pre-emption","difficulty":null,"sentence_number":6,"global_order":180,"speaker":"ARAN","english_text":"Nobody's got it. Go on.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Non ce l'ha nessuno. Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S01","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":1,"global_order":181,"speaker":"ARAN","english_text":"You know what breaks my heart? Go into any school. Find the kids who actually care — the ones making an effort — and open their workbooks. Highlighter. Page after page of highlighter. And the results are in: highlighting makes zero difference. Worse than zero — it costs them the time.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sai cosa mi spacca il cuore? Entra in una scuola qualsiasi. Trova i ragazzi a cui importa davvero — quelli che si impegnano — e apri i loro quaderni. Evidenziatore. Pagine e pagine di evidenziatore. E i risultati ci sono: evidenziare non fa nessuna differenza. Peggio di nessuna — gli costa il tempo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S02","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":2,"global_order":182,"speaker":"TOM","english_text":"And gives nothing back.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E non rende niente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S03","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":3,"global_order":183,"speaker":"ARAN","english_text":"Nothing. Nobody told them how a memory is made. Somebody, once, told them \"learn it\", and an older brother had a highlighter, so they're breaking their backs doing the one thing that's been shown not to work. And we let them. That's not their failure. That's ours.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Niente. Nessuno gli ha detto come si forma una memoria. Qualcuno, una volta, gli ha detto «imparalo», e un fratello più grande aveva un evidenziatore, e così si spaccano la schiena a fare l'unica cosa che è dimostrato che non funziona. E noi glielo lasciamo fare. Non è un fallimento loro. È nostro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S04","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":4,"global_order":184,"speaker":"TOM","english_text":"Ours.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Nostro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S05","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":5,"global_order":185,"speaker":"ARAN","english_text":"Ours. We're the generation that went through it and found out. Saying so is the job.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Nostro. Siamo la generazione che ci è passata e l'ha scoperto. Dirlo è il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S06","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":6,"global_order":186,"speaker":"TOM","english_text":"Then that's the first thing we say. Before the method. Before anything.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Allora è la prima cosa che diciamo. Prima del metodo. Prima di tutto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC30-S07","pod_slug":"method-pod-43-scene","scene_number":30,"scene_label":"Scene 30","scene_title":"L'evidenziatore","scene_subtitle":"MINT on 1:279–289 — the complaint, with a partner turn","difficulty":null,"sentence_number":7,"global_order":187,"speaker":"ARAN","english_text":"Before anything.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Prima di tutto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S01","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":1,"global_order":188,"speaker":"TOM","english_text":"Do you know how I introduce your method to people? I don't explain it. I say: you're in a drama class, it's a warm-up game, and the game is called Holy Dickhead Batman. Everyone shouts every combination they can make — Holy BatHead, ManDick. Holy DickMan, BatHead. It's stupid, it's fun, by the third one everybody's laughing — and they've just learnt that a unit of meaning is a thing you can move.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Sai come presento il tuo metodo alla gente? Non lo spiego. Dico: sei a lezione di teatro, è un gioco di riscaldamento, e il gioco si chiama Holy Dickhead Batman. Tutti gridano ogni combinazione che riescono a fare — Holy BatHead, ManDick. Holy DickMan, BatHead. È stupido, è divertente, al terzo ridono tutti — e hanno appena imparato che un'unità di significato è una cosa che si può spostare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S02","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":2,"global_order":189,"speaker":"ARAN","english_text":"That's it. And the thing you're giving them, without saying so, is permission.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Ecco. E la cosa che gli dai, senza dirlo, è il permesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S03","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":3,"global_order":190,"speaker":"TOM","english_text":"Permission.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Il permesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S04","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":4,"global_order":191,"speaker":"ARAN","english_text":"To play. Because most of the combinations are nonsense, and that's fine. You play, and every so often one lands as a real act of communication — and you get the feedback: oh. That one worked.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Di giocare. Perché quasi tutte le combinazioni non vogliono dire niente, e va bene così. Giochi, e ogni tanto una atterra come un vero atto di comunicazione — e ti arriva il feedback: oh. Quella ha funzionato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S05","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":5,"global_order":192,"speaker":"TOM","english_text":"And then everything clicks together. Like the end of a Star Wars film.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"E poi tutto si incastra. Come alla fine di un film di Guerre Stellari.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC31-S06","pod_slug":"method-pod-43-scene","scene_number":31,"scene_label":"Scene 31","scene_title":"Il gioco di riscaldamento","scene_subtitle":"the outsider's pitch","difficulty":null,"sentence_number":6,"global_order":193,"speaker":"ARAN","english_text":"…In a sense.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"…In un certo senso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S01","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":1,"global_order":194,"speaker":"ARAN","english_text":"So take a row of words — five of them, like this — and one link between each. That's the classic classroom: rich in words, poor in edges. …It's a pity the recording can't pick up my pathetic attempts to act this out.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Allora prendi una fila di parole — cinque, così — e un collegamento tra una e l'altra. Questa è l'aula classica: ricca di parole, povera di collegamenti. …Peccato che la registrazione non riesca a cogliere i miei patetici tentativi di mimarlo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S02","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":2,"global_order":195,"speaker":"TOM","english_text":"They'll get it. He's banging on the arm of the chair. Five bangs, in a row.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Lo capiranno. Sta battendo sul bracciolo della poltrona. Cinque colpi, in fila.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S03","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":3,"global_order":196,"speaker":"ARAN","english_text":"Five bangs in a row. And all you can do with five in a row is start here and walk to there. And that's boring — that's really boring. But now put another row under it, and another, so it's fifteen — and now draw every link there could be between them. Now I can start here and go through it fifteen different ways. And that's—","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Cinque colpi in fila. E con cinque in fila l'unica cosa che puoi fare è partire da qui e arrivare là. Ed è noioso — è davvero noioso. Ma adesso mettici un'altra fila sotto, e un'altra, così sono quindici — e adesso disegna tutti i collegamenti possibili tra loro. Adesso posso partire da qui e attraversarle in quindici modi diversi. E questo è—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S04","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":4,"global_order":197,"speaker":"TOM","english_text":"—the web.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"—la rete.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S05","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":5,"global_order":198,"speaker":"ARAN","english_text":"That's playful. That's the moment the adult learner thinks: oh, I can say a lot of different things. I'm in control of this. I'm enjoying it.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Questo è giocare. È il momento in cui l'adulto che impara pensa: oh, posso dire un sacco di cose diverse. Questa cosa la controllo io. Mi sto divertendo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S06","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":6,"global_order":199,"speaker":"TOM","english_text":"They really need to find a way to record hands, don't they.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Dovrebbero proprio trovare un modo di registrare le mani, eh?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC32-S07","pod_slug":"method-pod-43-scene","scene_number":32,"scene_label":"Scene 32","scene_title":"Le mani","scene_subtitle":"the medium named","difficulty":null,"sentence_number":7,"global_order":200,"speaker":"ARAN","english_text":"They really do.","author_notes":null,"created_at":"2026-08-30T19:35:32.605176+00:00","updated_at":"2026-08-30T19:35:32.605176+00:00","variant_key":null,"target_text":"Dovrebbero proprio.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC33-S01","pod_slug":"method-pod-43-scene","scene_number":33,"scene_label":"Scene 33","scene_title":"Un'email","scene_subtitle":"the world breaks in and is used","difficulty":null,"sentence_number":1,"global_order":201,"speaker":"ARAN","english_text":"IP is a disaster. The worst thing you can think of: I'm going to build something that would help every human alive, and then I'm going to stop humans using it. — Hang on. This is real time: an email, just now, from the people thinking of investing in us. \"We'll need details of your IP. We need to know there's IP before we can invest.\"","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"La proprietà intellettuale è un disastro. La cosa peggiore che puoi immaginare: costruisco una cosa che aiuterebbe ogni essere umano vivo, e poi impedisco agli esseri umani di usarla. — Aspetta. Questo è in diretta: un'email, adesso, dalle persone che stanno pensando di investire in noi. «Ci serviranno i dettagli della vostra proprietà intellettuale. Dobbiamo sapere che c'è, prima di investire.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC33-S02","pod_slug":"method-pod-43-scene","scene_number":33,"scene_label":"Scene 33","scene_title":"Un'email","scene_subtitle":"the world breaks in and is used","difficulty":null,"sentence_number":2,"global_order":202,"speaker":"TOM","english_text":"Of course they do.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Per forza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC33-S03","pod_slug":"method-pod-43-scene","scene_number":33,"scene_label":"Scene 33","scene_title":"Un'email","scene_subtitle":"the world breaks in and is used","difficulty":null,"sentence_number":3,"global_order":203,"speaker":"ARAN","english_text":"And I'm sitting here typing: yes, we've got IP, loads of it. Because we have.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"E io sono qui che scrivo: sì, ce l'abbiamo, un sacco. Perché ce l'abbiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC33-S04","pod_slug":"method-pod-43-scene","scene_number":33,"scene_label":"Scene 33","scene_title":"Un'email","scene_subtitle":"the world breaks in and is used","difficulty":null,"sentence_number":4,"global_order":204,"speaker":"TOM","english_text":"So. Horizon one. We are where we are, and we start where we are. You'd like to think in ideas and not worry about the rest, and so would I — and we both still need to eat.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ecco. Orizzonte uno. Siamo dove siamo, e partiamo da dove siamo. Ti piacerebbe pensare solo a idee e non preoccuparti del resto, e piacerebbe anche a me — e tutti e due dobbiamo ancora mangiare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC33-S05","pod_slug":"method-pod-43-scene","scene_number":33,"scene_label":"Scene 33","scene_title":"Un'email","scene_subtitle":"the world breaks in and is used","difficulty":null,"sentence_number":5,"global_order":205,"speaker":"ARAN","english_text":"We both still need to eat. Right — where was I. Defensive walls.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Tutti e due dobbiamo ancora mangiare. Bene — dov'ero rimasto. I muri difensivi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S01","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":1,"global_order":206,"speaker":"ARAN","english_text":"…and at the end of the month everybody wants you to pay it back. Hang on — what did you say, an hour ago? There's a fixed number of atoms on the planet.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"…e a fine mese tutti vogliono che tu glieli ripaghi. Aspetta — cos'hai detto, un'ora fa? Sul pianeta c'è un numero fisso di atomi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S02","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":2,"global_order":207,"speaker":"TOM","english_text":"We're not losing atoms of water.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Non stiamo perdendo atomi d'acqua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S03","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":3,"global_order":208,"speaker":"ARAN","english_text":"We're not losing atoms of water. So it's like atoms, isn't it. You make this much currency, it moves round all month, and at the end of the month it's all still here — it's just in the shops. You haven't lost any of it. You only have to know where it went.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Non stiamo perdendo atomi d'acqua. Quindi è come gli atomi, no? Fai questa quantità di moneta, gira per tutto il mese, e a fine mese è ancora tutta qui — è solo nei negozi. Non ne hai persa nemmeno un po'. Devi solo sapere dov'è andata.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S04","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":4,"global_order":209,"speaker":"TOM","english_text":"You've been saving that up.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Te la tenevi da parte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S05","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":5,"global_order":210,"speaker":"ARAN","english_text":"Since you said it. I was waiting for it to come round.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Da quando l'hai detta. Aspettavo che tornasse il momento.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S06","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":6,"global_order":211,"speaker":"TOM","english_text":"Good callback.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Bel richiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC34-S07","pod_slug":"method-pod-43-scene","scene_number":34,"scene_label":"Scene 34","scene_title":"Come gli atomi","scene_subtitle":"the callback","difficulty":null,"sentence_number":7,"global_order":212,"speaker":"ARAN","english_text":"Your atoms. I just gave them somewhere to go.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Sono i tuoi atomi. Io gli ho solo dato un posto dove andare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S01","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":1,"global_order":213,"speaker":"TOM","english_text":"I did a day of Mandarin last summer. One day. And another this year — different words, different structures, because you'd changed it all in between, obviously. And by the end of that second day I was thinking in Chinese. Not well. But it felt like more than a month of hard work would have given me, and I've done the month, in other languages, and I know what it buys.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"L'estate scorsa ho fatto un giorno di cinese. Un giorno. E un altro quest'anno — parole diverse, strutture diverse, perché nel frattempo avevi cambiato tutto, ovviamente. E alla fine di quel secondo giorno pensavo in cinese. Non bene. Ma sembrava più di quello che mi avrebbe dato un mese di lavoro duro, e il mese l'ho fatto, in altre lingue, e so cosa compra.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S02","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":2,"global_order":214,"speaker":"ARAN","english_text":"Two days, a year apart.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Due giorni, a un anno di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S03","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":3,"global_order":215,"speaker":"TOM","english_text":"A year apart.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"A un anno di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S04","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":4,"global_order":216,"speaker":"ARAN","english_text":"I've got mine on film. Manx — a conversation with a native speaker after day one, and another after day two, sixteen months later. Day one: fine, pleased with myself, not bad. Day two: the first real intimation of \"I can do this\" — still small, still a couple of hundred words, nowhere near seven hundred, but I could pick most of them up and turn them round. Something was going on.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"I miei ce li ho filmati. Manx — una conversazione con un madrelingua dopo il primo giorno, e un'altra dopo il secondo, sedici mesi dopo. Primo giorno: bene, contento di me, niente male. Secondo giorno: la prima vera avvisaglia di «ce la posso fare» — ancora piccola, ancora un paio di centinaia di parole, lontanissimo da settecento, ma quasi tutte le sapevo tirare fuori e girare. Stava succedendo qualcosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S05","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":5,"global_order":217,"speaker":"TOM","english_text":"Sixteen months apart.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"A sedici mesi di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC35-S06","pod_slug":"method-pod-43-scene","scene_number":35,"scene_label":"Scene 35","scene_title":"Un giorno di cinese","scene_subtitle":"story → matched story","difficulty":null,"sentence_number":6,"global_order":218,"speaker":"ARAN","english_text":"Two days. And you don't need the third one to know.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Due giorni. E non ti serve il terzo per saperlo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S01","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":1,"global_order":219,"speaker":"ARAN","english_text":"I have never once in my life thought: I want to learn Manx. Never. And I've done two days of it now — because it was an experiment, and there was a man willing to make the material, and I wanted to test some things. And now I've got unfinished business. I'm going to learn more Manx. I don't know if I'll ever be properly conversational in it — I really don't — but I'm going to learn more.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"In vita mia non ho mai pensato, nemmeno una volta: voglio imparare il manx. Mai. E adesso ne ho fatti due giorni — perché era un esperimento, e c'era uno disposto a fare il materiale, e volevo testare delle cose. E adesso ho un conto in sospeso. Imparerò altro manx. Non so se arriverò mai a parlarlo davvero — non lo so proprio — ma ne imparerò altro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S02","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":2,"global_order":220,"speaker":"TOM","english_text":"You don't know if you'll get there.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Non sai se ci arriverai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S03","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":3,"global_order":221,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S04","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":4,"global_order":222,"speaker":"TOM","english_text":"No. …That's allowed. Unfinished business is a good reason. Better than most.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"No. …È permesso. Un conto in sospeso è una buona ragione. Meglio di quasi tutte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S05","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":5,"global_order":223,"speaker":"ARAN","english_text":"It's the only reason I've ever actually needed.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"È l'unica ragione di cui abbia mai avuto davvero bisogno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC36-S06","pod_slug":"method-pod-43-scene","scene_number":36,"scene_label":"Scene 36","scene_title":"Il manx","scene_subtitle":"MINT partner turn on 2:258–263 — the disclosure acknowledged","difficulty":null,"sentence_number":6,"global_order":224,"speaker":"TOM","english_text":"Then learn more Manx.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora impara altro manx.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S01","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":1,"global_order":225,"speaker":"TOM","english_text":"Two days on molecular physics. In Hong Kong. Coming?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Due giorni di fisica molecolare. A Hong Kong. Vieni?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S02","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":2,"global_order":226,"speaker":"ARAN","english_text":"From anyone else: no. Sorry — molecular physics, not my thing. From you: yes. I've already said yes. Because you wouldn't have asked.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Da chiunque altro: no. Scusa — la fisica molecolare non fa per me. Da te: sì. Ho già detto di sì. Perché tu non me l'avresti chiesto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S03","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":3,"global_order":227,"speaker":"TOM","english_text":"I almost don't have to explain anything.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Quasi non devo nemmeno spiegare niente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S04","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":4,"global_order":228,"speaker":"ARAN","english_text":"You don't. What you're giving me isn't a recommendation, it's a guarantee — your personal guarantee — and that's what a tribe is. A dozen people who know what you'd find interesting, and go and find it, and bring it to you. The other version of that filter is somebody in California writing an algorithm, and that filter is driving all of us towards people who already agree with us. Your version is the antidote.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Non devi. Quello che mi dai non è un consiglio, è una garanzia — la tua garanzia personale — ed è questo una tribù. Una dozzina di persone che sanno cosa troveresti interessante, e vanno a cercarlo, e te lo portano. L'altra versione di quel filtro è qualcuno in California che scrive un algoritmo, e quel filtro ci sta spingendo tutti verso chi è già d'accordo con noi. La tua versione è l'antidoto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S05","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":5,"global_order":229,"speaker":"TOM","english_text":"So — Breton, for a weekend?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora — bretone, per un fine settimana?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC37-S06","pod_slug":"method-pod-43-scene","scene_number":37,"scene_label":"Scene 37","scene_title":"Perché sei tu","scene_subtitle":"the recommendation on personal guarantee","difficulty":null,"sentence_number":6,"global_order":230,"speaker":"ARAN","english_text":"Why not.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Perché no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S01","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":1,"global_order":231,"speaker":"ARAN","english_text":"I had one group with one truly negative person in it. And the most positive person in the room — the one you'd want in every group — paired up with her. On purpose. Good intentions: he was going to bring her round. And by the end of the day he'd become exactly as negative as she was. Not her better. Him worse.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ho avuto un gruppo con dentro una persona davvero negativa. E la persona più positiva della stanza — quella che vorresti in ogni gruppo — si è messa in coppia con lei. Apposta. Buone intenzioni: la avrebbe tirata su. E alla fine della giornata lui era diventato esattamente negativo quanto lei. Non lei meglio. Lui peggio.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S02","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":2,"global_order":232,"speaker":"TOM","english_text":"That's literally how cancer works.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"È letteralmente così che funziona il cancro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S03","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":3,"global_order":233,"speaker":"ARAN","english_text":"Exactly.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Esatto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S04","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":4,"global_order":234,"speaker":"TOM","english_text":"One cell, and the healthy one next to it.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Una cellula, e quella sana lì accanto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S05","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":5,"global_order":235,"speaker":"ARAN","english_text":"Exactly that. And nonetheless — that's the challenge, not the verdict. The group dynamic. Because if you solve for the dynamic, you've got something that's orders of magnitude more powerful than one person alone. It's just that \"solve for the dynamic\" is the whole job.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Esatto, proprio così. E ciò nonostante — quella è la sfida, non il verdetto. La dinamica del gruppo. Perché se risolvi la dinamica, hai una cosa più potente di ordini di grandezza rispetto a una persona da sola. È solo che «risolvere la dinamica» è tutto il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC38-S06","pod_slug":"method-pod-43-scene","scene_number":38,"scene_label":"Scene 38","scene_title":"Come il cancro","scene_subtitle":"the listener names it","difficulty":null,"sentence_number":6,"global_order":236,"speaker":"TOM","english_text":"Then it's the whole job.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora è tutto il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S01","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":1,"global_order":237,"speaker":"TOM","english_text":"So when's day three?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora, il terzo giorno quand'è?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S02","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":2,"global_order":238,"speaker":"ARAN","english_text":"…That's on me. I've been waiting. I told myself I needed fifteen new dialogues for a day, and I haven't got fifteen, and I've sat on that for a year as if it were a reason. It isn't. It's an excuse with a number on it. I've got seven, maybe eight — enough for half a day. So I stop waiting, and do the half day, and the half day is the price of having waited.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"…Questa è colpa mia. Sono stato ad aspettare. Mi ero detto che per un giorno mi servivano quindici dialoghi nuovi, e quindici non ce li ho, e ci sono rimasto seduto sopra per un anno come se fosse una ragione. Non lo è. È una scusa con un numero attaccato. Ne ho sette, forse otto — bastano per mezza giornata. Quindi smetto di aspettare, e faccio la mezza giornata, e la mezza giornata è il prezzo di aver aspettato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S03","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":3,"global_order":239,"speaker":"TOM","english_text":"Half a day.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Mezza giornata.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S04","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":4,"global_order":240,"speaker":"ARAN","english_text":"Half a day. With the seven.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Mezza giornata. Con i sette.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S05","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":5,"global_order":241,"speaker":"TOM","english_text":"Then that's day three. Nobody said days come in one size.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora è quello il terzo giorno. Nessuno ha detto che i giorni vengono in una taglia sola.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC39-S06","pod_slug":"method-pod-43-scene","scene_number":39,"scene_label":"Scene 39","scene_title":"Ho smesso di aspettare","scene_subtitle":"MINT partner turn on 1:404–406 — trouble that is your own fault","difficulty":null,"sentence_number":6,"global_order":242,"speaker":"ARAN","english_text":"Nobody did. I did.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Nessuno. L'ho detto io.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S01","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":1,"global_order":243,"speaker":"TOM","english_text":"Right. This is Tom and Aran Talk Bollocks, part four. Today we've got—","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Bene. Questo è Tom e Aran Talk Bollocks, parte quattro. Oggi abbiamo—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S02","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":2,"global_order":244,"speaker":"ARAN","english_text":"The future of education?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Il futuro dell'istruzione?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S03","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":3,"global_order":245,"speaker":"TOM","english_text":"The future of life, the universe, and education.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Il futuro della vita, dell'universo, e dell'istruzione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S04","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":4,"global_order":246,"speaker":"ARAN","english_text":"Are you going to put \"part four of eighteen million\"?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ci scrivi «parte quattro di diciotto milioni»?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S05","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":5,"global_order":247,"speaker":"TOM","english_text":"Who knows. Let's just start anywhere. You start.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Chi lo sa. Partiamo da un punto qualsiasi. Comincia tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S06","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":6,"global_order":248,"speaker":"ARAN","english_text":"The broad picture — and I'll say it fast because it's big — is that none of this happens on its own. Schooling is one piece of a complex adaptive system, and the end of the game has to be seven billion connected, happy, enthusiastic minds who can solve complicated problems—","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Il quadro generale — e lo dico veloce perché è grande — è che niente di tutto questo succede da solo. La scuola è un pezzo di un sistema adattivo complesso, e la fine del gioco devono essere sette miliardi di menti connesse, felici, entusiaste, capaci di risolvere problemi complicati—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S07","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":7,"global_order":249,"speaker":"TOM","english_text":"Do some cool shit.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Fare cose fighe.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC40-S08","pod_slug":"method-pod-43-scene","scene_number":40,"scene_label":"Scene 40","scene_title":"Parte quattro","scene_subtitle":"the ritual open, at the summit","difficulty":null,"sentence_number":8,"global_order":250,"speaker":"ARAN","english_text":"—very, very quickly. Yes. That.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"—molto, molto in fretta. Sì. Quello.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S01","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":1,"global_order":251,"speaker":"TOM","english_text":"Before anything else. You owed me a third thing.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Prima di tutto il resto. Mi dovevi una terza cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S02","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":2,"global_order":252,"speaker":"ARAN","english_text":"I owed you a third thing.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ti dovevo una terza cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S03","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":3,"global_order":253,"speaker":"TOM","english_text":"The dog. You said \"the third thing, and this is the important one, is that when you actually—\" and then the dog.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Il cane. Hai detto «la terza cosa, ed è quella importante, è che quando tu davvero—» e poi il cane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S04","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":4,"global_order":254,"speaker":"ARAN","english_text":"And then the dog. …I've lost it.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"E poi il cane. …L'ho persa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S05","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":5,"global_order":255,"speaker":"TOM","english_text":"You've lost the important one.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Hai perso quella importante.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S06","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":6,"global_order":256,"speaker":"ARAN","english_text":"I've lost the important one. Give me the first two.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ho perso quella importante. Dammi le prime due.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S07","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":7,"global_order":257,"speaker":"TOM","english_text":"One: the evening class is short on edges. Two: it's short on repetition, so by next week it's gone. Three: \"when you actually—\"","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Uno: il corso serale è povero di collegamenti. Due: è povero di ripetizione, e la settimana dopo è tutto sparito. Tre: «quando tu davvero—»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S08","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":8,"global_order":258,"speaker":"ARAN","english_text":"—go and use it. Yes. That's it. When you actually go and use it — if you've already walked the paths, it isn't a step-change any more. It's the same thing you've been doing, in a bigger room. That's the third thing. That's the whole reason it works.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"—vai a usarla. Sì. È quella. Quando vai davvero a usarla — se hai già percorso i sentieri, non è più un salto. È la stessa cosa che facevi già, in una stanza più grande. Questa è la terza cosa. È tutto il motivo per cui funziona.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S09","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":9,"global_order":259,"speaker":"TOM","english_text":"Debt paid.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Debito saldato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC41-S10","pod_slug":"method-pod-43-scene","scene_number":41,"scene_label":"Scene 41","scene_title":"La terza cosa","scene_subtitle":"MINT — the thread recovered (sibling to Scene 14)","difficulty":null,"sentence_number":10,"global_order":260,"speaker":"ARAN","english_text":"Debt paid. Never let a dog near the important one.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Debito saldato. Mai lasciare un cane vicino a quella importante.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S01","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":1,"global_order":261,"speaker":"TOM","english_text":"Here's what I actually want. Ten languages, in parallel, one day a year each. Three years, and I'm speaking all ten — badly, and happily. Minimum total effort. That's the only thing I care about.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ecco cosa voglio davvero. Dieci lingue, in parallelo, un giorno all'anno ciascuna. Tre anni, e le parlo tutte e dieci — male, e felice. Minimo sforzo totale. È l'unica cosa che mi interessa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S02","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":2,"global_order":262,"speaker":"ARAN","english_text":"No. You care about efficiency until you need something. You need Chinese by October. So one day a year for ten years isn't going to win — you dive in and hammer at it, seventy-five dialogues in ten days, and you don't care what it costs. Efficiency is lovely. But so is speed, and speed is the one that answers to a date.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"No. Ti interessa l'efficienza finché non ti serve qualcosa. Ti serve il cinese per ottobre. Quindi un giorno all'anno per dieci anni non vince — ti butti dentro e ci martelli sopra, settantacinque dialoghi in dieci giorni, e non ti importa quanto costa. L'efficienza è bellissima. Ma lo è anche la velocità, e la velocità è quella che risponde a una data.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S03","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":3,"global_order":263,"speaker":"TOM","english_text":"Speed is a feeling. Efficiency is a number.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"La velocità è una sensazione. L'efficienza è un numero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S04","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":4,"global_order":264,"speaker":"ARAN","english_text":"Speed is the number that matters to the person who needs it. Efficiency is the number that matters to the person designing the course.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"La velocità è il numero che conta per chi ne ha bisogno. L'efficienza è il numero che conta per chi progetta il corso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S05","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":5,"global_order":265,"speaker":"TOM","english_text":"Then we're not going to agree.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Allora non ci metteremo d'accordo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S06","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":6,"global_order":266,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S07","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":7,"global_order":267,"speaker":"TOM","english_text":"Good. Leave it standing. I build for efficiency, you sell it for speed, and the learners tell us which of us was right.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Bene. Lasciamolo in piedi. Io costruisco per l'efficienza, tu lo vendi per la velocità, e chi impara ci dirà chi di noi due aveva ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC42-S08","pod_slug":"method-pod-43-scene","scene_number":42,"scene_label":"Scene 42","scene_title":"Efficienza e velocità","scene_subtitle":"MINT — the standing clash (sibling to Scene 16)","difficulty":null,"sentence_number":8,"global_order":268,"speaker":"ARAN","english_text":"Standing. Next thing.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"In piedi. Prossima cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S01","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":1,"global_order":269,"speaker":"TOM","english_text":"Right. That's the hour. Let's stop there.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Bene. È passata l'ora. Fermiamoci qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S02","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":2,"global_order":270,"speaker":"ARAN","english_text":"One thing. Somebody at Cardiff: the routes to four thousand words are all different. After four thousand, they're all the same.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Una cosa. Uno a Cardiff: le strade per arrivare a quattromila parole sono tutte diverse. Dopo le quattromila, sono tutte uguali.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S03","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":3,"global_order":271,"speaker":"TOM","english_text":"Interesting. …No. Hang on. Four thousand?","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Interessante. …No. Aspetta. Quattromila?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S04","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":4,"global_order":272,"speaker":"ARAN","english_text":"Four thousand. Below it, every method looks different — whatever road you took. Above it, nobody can tell which one you used; from there it's only how often you use the language. So the whole argument we've been having is about the road to four thousand, and after that the road doesn't exist.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Quattromila. Sotto, ogni metodo sembra diverso — qualunque strada tu abbia preso. Sopra, nessuno sa dire quale hai usato; da lì in poi conta solo quanto spesso usi la lingua. Quindi tutta la discussione che stiamo facendo è sulla strada fino a quattromila, e dopo la strada non esiste.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S05","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":5,"global_order":273,"speaker":"TOM","english_text":"We're not stopping.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Non ci fermiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S06","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":6,"global_order":274,"speaker":"ARAN","english_text":"You said the hour.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Hai detto l'ora.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S07","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":7,"global_order":275,"speaker":"TOM","english_text":"I said the hour. Stop the recording, start another one. Part two. Now.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Ho detto l'ora. Ferma la registrazione, fanne partire un'altra. Parte due. Adesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-43-scene:SC43-S08","pod_slug":"method-pod-43-scene","scene_number":43,"scene_label":"Scene 43","scene_title":"Quattromila parole","scene_subtitle":"the resisted goodbye (half-attested)","difficulty":null,"sentence_number":8,"global_order":276,"speaker":"ARAN","english_text":"Now.","author_notes":null,"created_at":"2026-08-30T19:35:32.7308+00:00","updated_at":"2026-08-30T19:35:32.7308+00:00","variant_key":null,"target_text":"Adesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S01","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":1,"global_order":1,"speaker":"TOM","english_text":"Right. This is Tom and Aran Talk Bollocks, part four. Today we've got—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Bene. Questo è Tom e Aran Talk Bollocks, parte quattro. Oggi abbiamo—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S02","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":2,"global_order":2,"speaker":"ARAN","english_text":"The future of education?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Il futuro dell'istruzione?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S03","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":3,"global_order":3,"speaker":"TOM","english_text":"The future of life, the universe, and education.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Il futuro della vita, dell'universo, e dell'istruzione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S04","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":4,"global_order":4,"speaker":"ARAN","english_text":"Are you going to put \"part four of eighteen million\"?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ci scrivi «parte quattro di diciotto milioni»?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S05","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":5,"global_order":5,"speaker":"TOM","english_text":"Who knows. Let's just start anywhere. You start.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Chi lo sa. Partiamo da un punto qualsiasi. Comincia tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S06","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":6,"global_order":6,"speaker":"ARAN","english_text":"The broad picture — and I'll say it fast because it's big — is that none of this happens on its own. Schooling is one piece of a complex adaptive system, and the end of the game has to be seven billion connected, happy, enthusiastic minds who can solve complicated problems—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Il quadro generale — e lo dico veloce perché è grande — è che niente di tutto questo succede da solo. La scuola è un pezzo di un sistema adattivo complesso, e la fine del gioco devono essere sette miliardi di menti connesse, felici, entusiaste, capaci di risolvere problemi complicati—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S07","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":7,"global_order":7,"speaker":"TOM","english_text":"Do some cool shit.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Fare cose fighe.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S08","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":8,"global_order":8,"speaker":"ARAN","english_text":"—very, very quickly. Yes. That. So — start small. Start with the smallest thing there is. What does it mean to know a word?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"—molto, molto in fretta. Sì. Quello. Allora — partiamo dal piccolo. Dalla cosa più piccola che c'è. Cosa vuol dire conoscere una parola?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S09","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":9,"global_order":9,"speaker":"TOM","english_text":"It's not that you know the words. You know what's between the words. The edges. Like a city — you don't know a city because you know the buildings; you know it because you know the streets. You can name every building in Rome and still not be able to get from one to the next. So a new word without streets…","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non è che conosci le parole. Conosci quello che c'è tra le parole. I collegamenti. Come una città — non conosci una città perché conosci i palazzi; la conosci perché conosci le strade. Puoi sapere il nome di ogni palazzo di Roma e non riuscire comunque ad andare da uno all'altro. Quindi una parola nuova senza strade…","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S10","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":10,"global_order":10,"speaker":"ARAN","english_text":"…is a building in the middle of a field.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…è un palazzo in mezzo a un campo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S11","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":11,"global_order":11,"speaker":"TOM","english_text":"Exactly that.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Esatto, proprio così.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S12","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":12,"global_order":12,"speaker":"ARAN","english_text":"Nobody lives there.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non ci abita nessuno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S13","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":13,"global_order":13,"speaker":"TOM","english_text":"Nobody lives there. And schools keep building them. Poor things.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non ci abita nessuno. E le scuole continuano a costruirli. Poverini.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S14","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":14,"global_order":14,"speaker":"ARAN","english_text":"Poor things, the buildings or the schools?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Poverini chi, i palazzi o le scuole?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S15","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":15,"global_order":15,"speaker":"TOM","english_text":"Both. Show me the classroom version.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tutti e due. Fammi vedere la versione da aula.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S16","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":16,"global_order":16,"speaker":"ARAN","english_text":"So take a row of words — five of them, like this — and one link between each. That's the classic classroom: rich in words, poor in edges. …It's a pity the recording can't pick up my pathetic attempts to act this out.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora prendi una fila di parole — cinque, così — e un collegamento tra una e l'altra. Questa è l'aula classica: ricca di parole, povera di collegamenti. …Peccato che la registrazione non riesca a cogliere i miei patetici tentativi di mimarlo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S17","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":17,"global_order":17,"speaker":"TOM","english_text":"They'll get it. He's banging on the arm of the chair. Five bangs, in a row.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Lo capiranno. Sta battendo sul bracciolo della poltrona. Cinque colpi, in fila.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S18","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":18,"global_order":18,"speaker":"ARAN","english_text":"Five bangs in a row. And all you can do with five in a row is start here and walk to there. And that's boring — that's really boring, and it's what most people were ever given. But now put another row under it, and another, so it's fifteen — and now draw every link there could be between them. Now I can start here and go through it fifteen different ways, and nobody taught me any of the fifteen. And that's—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Cinque colpi in fila. E con cinque in fila l'unica cosa che puoi fare è partire da qui e arrivare là. Ed è noioso — è davvero noioso, ed è quello che quasi tutti hanno sempre avuto. Ma adesso mettici un'altra fila sotto, e un'altra, così sono quindici — e adesso disegna tutti i collegamenti possibili tra loro. Adesso posso partire da qui e attraversarle in quindici modi diversi, e nessuno dei quindici me l'ha insegnato. E questo è—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S19","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":19,"global_order":19,"speaker":"TOM","english_text":"—the web.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"—la rete.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S20","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":20,"global_order":20,"speaker":"ARAN","english_text":"That's playful. That's the moment the adult learner thinks: oh, I can say a lot of different things. I'm in control of this. Try it. After \"red\", what can I say? \"Red bus.\" \"A red house.\" \"One that's red.\" A lot. And what can't I say? I can't say \"red but\".","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Questo è giocare. È il momento in cui l'adulto che impara pensa: oh, posso dire un sacco di cose diverse. Questa cosa la controllo io. Prova. Dopo «rosso», cosa posso dire? «Autobus rosso.» «Una casa rossa.» «Uno rosso.» Tanto. E cosa non posso dire? Non posso dire «rosso ma».","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S21","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":21,"global_order":21,"speaker":"TOM","english_text":"\"I'd like one that's red — but I don't mind.\"","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"«Vorrei uno rosso — ma non importa.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S22","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":22,"global_order":22,"speaker":"ARAN","english_text":"…You can. I said you can't, and you can. Good. So after \"red\" there is a \"but\" — with a little something in it. Now I know one more. So do you.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…Puoi. Ho detto che non puoi, e puoi. Bene. Quindi dopo «rosso» c'è un «ma» — con qualcosina in mezzo. Adesso ne so una in più. Anche tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S23","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":23,"global_order":23,"speaker":"TOM","english_text":"A small one.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Piccola, però.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S24","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":24,"global_order":24,"speaker":"ARAN","english_text":"All of it is small. That's the language.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È tutto piccolo. È la lingua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S25","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":25,"global_order":25,"speaker":"TOM","english_text":"Fifteen small things, and every road between them.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindici cose piccole, e tutte le strade in mezzo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S26","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":26,"global_order":26,"speaker":"ARAN","english_text":"And not one building in a field. They really need to find a way to record hands, don't they.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E nemmeno un palazzo in mezzo al campo. Dovrebbero proprio trovare un modo di registrare le mani, eh?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC01-S27","pod_slug":"method-pod-chapters","scene_number":1,"scene_label":"Chapter 1","scene_title":"Parte quattro","scene_subtitle":"knowing a language is knowing what is between the words","difficulty":null,"sentence_number":27,"global_order":27,"speaker":"TOM","english_text":"They really do.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Dovrebbero proprio.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S01","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":1,"global_order":28,"speaker":"ARAN","english_text":"I've got a story. It proves nothing — accept it anyway.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ho una storia. Non dimostra niente — accettala lo stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S02","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":2,"global_order":29,"speaker":"TOM","english_text":"Go on.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-09-03T23:24:13.899736+00:00","variant_key":null,"target_text":"Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S03","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":3,"global_order":30,"speaker":"ARAN","english_text":"A learner writes to me: the words she remembers are the ones that cost her effort. The easy ones, the ones that came free — gone. Every single one. And she's cross about it, because the easy ones were the ones she liked.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Una studentessa mi scrive: le parole che ricorda sono quelle che le sono costate fatica. Quelle facili, quelle venute gratis — sparite. Tutte quante. Ed è arrabbiata, perché quelle facili erano quelle che le piacevano.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S04","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":4,"global_order":31,"speaker":"TOM","english_text":"One learner. You're building a church on one learner?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Una studentessa. Stai costruendo una chiesa su una studentessa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S05","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":5,"global_order":32,"speaker":"ARAN","english_text":"I said it proves nothing. But you'll remember it, won't you?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ho detto che non dimostra niente. Ma tu te la ricorderai, no?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S06","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":6,"global_order":33,"speaker":"TOM","english_text":"…That's a dirty trick. Yes.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…Che colpo basso. Sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S07","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":7,"global_order":34,"speaker":"ARAN","english_text":"It's the same trick every time. Fish, in Welsh: pysgod.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È sempre lo stesso trucco. Pesce, in gallese: pysgod.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S08","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":8,"global_order":35,"speaker":"TOM","english_text":"Pysgod.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Pysgod.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S09","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":9,"global_order":36,"speaker":"ARAN","english_text":"Now, if I just make you say it — pysgod, pysgod, pysgod — you're not making a memory. It's too easy.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ora, se ti faccio solo ripetere — pysgod, pysgod, pysgod — non stai formando una memoria. È troppo facile.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S10","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":10,"global_order":37,"speaker":"TOM","english_text":"…Actually I've half got it already. \"Pys\" — a bit like puss, the cat. And \"cod\" is a fish. Pysgod.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…In realtà l'ho già mezzo preso. «Pys» — un po' come puss, il gatto. E «cod» è un pesce. Pysgod.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S11","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":11,"global_order":38,"speaker":"ARAN","english_text":"There. Look at what you just did. I didn't ask you for that. You went looking for a hook, on your own, and the hook cost you something — and that's the memory, not the word. Now: if we leave it there, and in two hours I come back and ask you the Welsh for fish, it'll be hard. And the hard is the point. If it were easy, by next week it would be gone. That's the curve.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ecco. Guarda cos'hai appena fatto. Non te l'avevo chiesto. Sei andato a cercarti un gancio, da solo, e il gancio ti è costato qualcosa — e la memoria è quella, non la parola. Ora: se lo lasciamo lì, e tra due ore torno e ti chiedo il gallese per pesce, sarà difficile. E il difficile è il punto. Se fosse facile, la settimana prossima sarebbe sparito. È la curva.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S12","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":12,"global_order":39,"speaker":"TOM","english_text":"So you're going to leave it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi lo lasci lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S13","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":13,"global_order":40,"speaker":"ARAN","english_text":"I'm going to leave it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Lo lascio lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S14","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":14,"global_order":41,"speaker":"TOM","english_text":"Pysgod. …The curve, though. Ebbinghaus. The German. One man, memorising lists of nonsense syllables, testing himself, sample size one, corroborated by nobody — and a hundred years later everyone still quotes his intervals as if they were physics. And yet the practice works. There's truth in the practice without any consistency about the why.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Pysgod. …La curva, però. Ebbinghaus. Il tedesco. Un uomo solo, che impara a memoria liste di sillabe senza senso, si testa da solo, campione di uno, confermato da nessuno — e cent'anni dopo tutti citano ancora i suoi intervalli come se fossero fisica. Eppure la pratica funziona. C'è del vero nella pratica, senza nessuna coerenza sul perché.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S15","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":15,"global_order":42,"speaker":"ARAN","english_text":"That's exactly where I was about to go.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È esattamente lì che stavo per andare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S16","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":16,"global_order":43,"speaker":"TOM","english_text":"Was it?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Davvero?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S17","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":17,"global_order":44,"speaker":"ARAN","english_text":"Word for word. I'd lost his name, but that's the turn. So take it — you're already there.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Parola per parola. Mi era sfuggito il nome, ma la svolta è quella. Quindi prenditela — ci sei già.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S18","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":18,"global_order":45,"speaker":"TOM","english_text":"Then I'll take it. Because it's the same church. One German on one German, one learner on one learner, and one of us on himself with a Welsh fish. So — wait. How do we know that?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-09-03T23:24:14.301352+00:00","variant_key":null,"target_text":"Allora me la prendo. Perché è la stessa chiesa. Un tedesco su un tedesco, una studentessa su una studentessa, e uno di noi due su se stesso con un pesce gallese. Allora — aspetta. Come lo sappiamo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S19","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":19,"global_order":46,"speaker":"ARAN","english_text":"Know what?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Come sappiamo cosa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S20","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":20,"global_order":47,"speaker":"TOM","english_text":"That it's effort that makes the memory. I feel it's true. It seems to work. But where are we, actually — is it in the studies, peer-reviewed, mapped out, can we say \"proven scientific fact\"? Or is it one man in California with a good idea, and us with a feeling?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Che è la fatica a fare la memoria. Io sento che è vero. Sembra funzionare. Ma a che punto siamo, davvero — è negli studi, con la peer review, tutto mappato, possiamo dire «fatto scientifico dimostrato»? O è un signore in California con una buona idea, e noi con una sensazione?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S21","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":21,"global_order":48,"speaker":"ARAN","english_text":"…It's closer to the man in California. Bjork says it, and he's careful, and the work is good. Proven? No. What I've got on top of that is me — one person, testing himself for years — and now a fish you'll have or not have in two hours. That's not proof, that's a story with a flag on it. But the question you just asked is the right one, and nobody asks it enough. So — no. We don't know. We think.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…È più vicino al signore in California. Lo dice Bjork, ed è uno attento, e il lavoro è buono. Dimostrato? No. Quello che ho in più è me stesso — una persona, che si testa da sola da anni — e adesso un pesce che tra due ore avrai o non avrai. Non è una prova, è una storia con una bandierina sopra. Ma la domanda che hai appena fatto è quella giusta, e nessuno la fa abbastanza. Quindi — no. Non lo sappiamo. Lo pensiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S22","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":22,"global_order":49,"speaker":"TOM","english_text":"\"We think\" I can live with.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Con «lo pensiamo» posso convivere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S23","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":23,"global_order":50,"speaker":"ARAN","english_text":"\"We think\" is where every good thing starts. And you'll still remember the fish.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"«Lo pensiamo» è da dove parte ogni cosa buona. E il pesce te lo ricorderai lo stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC02-S24","pod_slug":"method-pod-chapters","scene_number":2,"scene_label":"Chapter 2","scene_title":"La fatica","scene_subtitle":"effort makes the memory, and how much do we actually know that","difficulty":null,"sentence_number":24,"global_order":51,"speaker":"TOM","english_text":"Stop that.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Smettila.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S01","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":1,"global_order":52,"speaker":"TOM","english_text":"Can we try again? More slowly.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Possiamo riprovare? Più lentamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S02","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":2,"global_order":53,"speaker":"ARAN","english_text":"Of course.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Certo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S03","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":3,"global_order":54,"speaker":"TOM","english_text":"I don't need all the words. I need three. Three words. No — two. Two words, and I can talk all day.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non mi servono tutte le parole. Me ne servono tre. Tre parole. No — due. Due parole, e posso parlare tutto il giorno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S04","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":4,"global_order":55,"speaker":"ARAN","english_text":"You said three.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Hai detto tre.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S05","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":5,"global_order":56,"speaker":"TOM","english_text":"The third one is you.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"La terza sei tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S06","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":6,"global_order":57,"speaker":"ARAN","english_text":"Very well. That's enough for me. Which two?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Benissimo. A me basta. Quali due?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S07","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":7,"global_order":58,"speaker":"TOM","english_text":"Any two.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Due qualsiasi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S08","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":8,"global_order":59,"speaker":"ARAN","english_text":"Any two?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Due qualsiasi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S09","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":9,"global_order":60,"speaker":"TOM","english_text":"Two words, and you. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Due parole, e tu. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S10","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":10,"global_order":61,"speaker":"ARAN","english_text":"Say it again — for the people who think they need all of them.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Dillo ancora — per quelli che pensano di averne bisogno tutte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S11","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":11,"global_order":62,"speaker":"TOM","english_text":"I think that when you learn a language you don't need all the words — you need the words you can say something with, and after that you talk, and you talk, and you talk, all day, with people, and after that you have more words, and then you talk more, and then—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Penso che quando impari una lingua non ti servano tutte le parole — ti servono le parole con cui puoi dire qualcosa, e dopo parli, e parli, e parli, tutto il giorno, con la gente, e dopo hai più parole, e poi parli di più, e poi—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S12","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":12,"global_order":63,"speaker":"ARAN","english_text":"I don't understand.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non ho capito.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S13","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":13,"global_order":64,"speaker":"TOM","english_text":"You don't understand?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non hai capito?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S14","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":14,"global_order":65,"speaker":"ARAN","english_text":"No. Too much. Again — slowly.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No. Troppo. Ancora — lentamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S15","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":15,"global_order":66,"speaker":"TOM","english_text":"You don't need all the words.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non ti servono tutte le parole.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S16","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":16,"global_order":67,"speaker":"ARAN","english_text":"Yes. Now I understand.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Sì. Adesso ho capito.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S17","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":17,"global_order":68,"speaker":"TOM","english_text":"Good. That's all. — And I've just done the thing. Two words would have done it, and I gave you forty.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Bene. Tutto qui. — E ho appena fatto io la cosa. Bastavano due parole, e te ne ho date quaranta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S18","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":18,"global_order":69,"speaker":"ARAN","english_text":"Everybody does the thing. We did it for years. For years we said it: three words of a language, an empty gesture. Classic tokenism. We used to laugh about it, honestly. And we were utterly wrong.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"La fanno tutti, la cosa. L'abbiamo fatta per anni anche noi. Per anni l'abbiamo detto: tre parole di una lingua, un gesto vuoto. Tokenismo classico. Ci ridevamo sopra, sinceramente. E ci sbagliavamo completamente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S19","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":19,"global_order":70,"speaker":"TOM","english_text":"Completely wrong?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Completamente?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S20","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":20,"global_order":71,"speaker":"ARAN","english_text":"Utterly. Every single one of those people — three words, said with effort, badly, in the wrong order — made a connection that wouldn't have been there otherwise, and they didn't have to learn anything else at all. Three words open a door, and the door stays open.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Completamente. Ognuna di quelle persone — tre parole, dette con fatica, male, nell'ordine sbagliato — ha creato un legame che altrimenti non ci sarebbe stato, e non hanno dovuto imparare nient'altro. Tre parole aprono una porta, e la porta resta aperta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S21","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":21,"global_order":72,"speaker":"TOM","english_text":"And they cost the person almost nothing. That still amazes me.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E alla persona non costano quasi niente. Questo mi stupisce ancora.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S22","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":22,"global_order":73,"speaker":"ARAN","english_text":"Three words. You said two.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tre parole. Tu avevi detto due.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC03-S23","pod_slug":"method-pod-chapters","scene_number":3,"scene_label":"Chapter 3","scene_title":"Due parole","scene_subtitle":"how little you need to begin","difficulty":null,"sentence_number":23,"global_order":74,"speaker":"TOM","english_text":"The third one is still you.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"La terza sei sempre tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S01","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":1,"global_order":75,"speaker":"TOM","english_text":"So the rules of grammar — where do they live, in the head?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi le regole della grammatica — dove stanno, nella testa?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S02","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":2,"global_order":76,"speaker":"ARAN","english_text":"Ask the question at the level of neurons. How would it even work?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Fai la domanda al livello dei neuroni. Come funzionerebbe, anche solo in teoria?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S03","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":3,"global_order":77,"speaker":"TOM","english_text":"A parallel system? Word types, categories, a machine for putting them in order, and another machine to check the first one, and somewhere to keep all of that, and a way to learn it as a child, before you can tie your shoes…","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Un sistema parallelo? Tipi di parole, categorie, una macchina per metterle in ordine, e un'altra macchina che controlla la prima, e un posto dove tenere tutto questo, e un modo per impararlo da bambino, prima ancora di saperti allacciare le scarpe…","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S04","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":4,"global_order":78,"speaker":"ARAN","english_text":"Listen to yourself. It gets complicated very fast.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ascoltati. Diventa complicato molto in fretta.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S05","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":5,"global_order":79,"speaker":"TOM","english_text":"And so?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E quindi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S06","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":6,"global_order":80,"speaker":"ARAN","english_text":"It's complicated — so it can't be a thing. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È complicato — quindi non può essere una cosa vera. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S07","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":7,"global_order":81,"speaker":"TOM","english_text":"So what you're saying is: there are no rules.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi quello che stai dicendo è: le regole non esistono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S08","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":8,"global_order":82,"speaker":"ARAN","english_text":"No. That's not what I'm saying. The rules exist — they're in the book, they're a perfectly good description of what comes out of people's mouths. What I'm saying is that there's nothing in the head that stores the description. A map of Rome is a good map. Rome doesn't keep a copy. Whatever is in there that makes the sentences, it isn't the rules — the rules are what we wrote down afterwards, looking at the sentences.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No. Non è quello che dico. Le regole esistono — stanno nel libro, sono una descrizione perfettamente buona di quello che esce dalla bocca della gente. Quello che dico è che nella testa non c'è niente che conservi la descrizione. Una mappa di Roma è una buona mappa. Roma non ne tiene una copia. Qualunque cosa ci sia là dentro a fare le frasi, non sono le regole — le regole sono quello che abbiamo scritto dopo, guardando le frasi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S09","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":9,"global_order":83,"speaker":"TOM","english_text":"Then what's in there?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E allora cosa c'è là dentro?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S10","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":10,"global_order":84,"speaker":"ARAN","english_text":"I don't know.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non lo so.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S11","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":11,"global_order":85,"speaker":"TOM","english_text":"You don't know?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non lo sai?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S12","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":12,"global_order":86,"speaker":"ARAN","english_text":"No. I don't know, and you don't know. Is it a good idea? I don't know. Is it a bad idea? I don't know. And you don't know.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No. Io non lo so, e tu non lo sai. È una buona idea? Non lo so. È una cattiva idea? Non lo so. E tu non lo sai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S13","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":13,"global_order":87,"speaker":"TOM","english_text":"You're right. I don't know.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Hai ragione. Non lo so.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S14","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":14,"global_order":88,"speaker":"ARAN","english_text":"Good. Now we can start to think. What do you think?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Bene. Adesso possiamo iniziare a pensare. Tu cosa pensi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S15","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":15,"global_order":89,"speaker":"TOM","english_text":"I think — whatever it is — it isn't made of words.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Penso che — qualunque cosa sia — non sia fatta di parole.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S16","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":16,"global_order":90,"speaker":"ARAN","english_text":"Ah. Now. There's a researcher — Wray, formulaic language, very highly regarded — and for a few years she's been saying, in conversation, I don't think she's published it: there is no such thing as a word.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ah. Ecco. C'è una ricercatrice — Wray, linguaggio formulaico, molto stimata — e da qualche anno dice, in conversazione, non credo l'abbia pubblicato: le parole non esistono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S17","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":17,"global_order":91,"speaker":"TOM","english_text":"No such thing.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non esistono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S18","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":18,"global_order":92,"speaker":"ARAN","english_text":"There aren't any. We use the word \"word\" for something that doesn't really exist and isn't a helpful way of cutting things up. And every time I've heard her say it I've thought: I can't keep up with this, my brain already hurts. And she's right, and I still can't keep up.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non ce ne sono. Usiamo la parola «parola» per una cosa che in realtà non esiste, e che non è un modo utile di tagliare le cose. E ogni volta che gliel'ho sentito dire ho pensato: non ce la faccio a starle dietro, mi fa già male il cervello. E ha ragione, e continuo a non starle dietro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S19","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":19,"global_order":93,"speaker":"TOM","english_text":"She'd allow a syllable. A sound. Things that start and stop.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Una sillaba la concederebbe. Un suono. Cose che iniziano e finiscono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S20","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":20,"global_order":94,"speaker":"ARAN","english_text":"Yes. So — we'd all say \"to boldly go\" is three words. And by most of the ways you could actually define a word, it's one. And then you're into woo.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Sì. Allora — diremmo tutti che «to boldly go» sono tre parole. E per quasi tutti i modi in cui potresti davvero definire una parola, è una. E poi finisci nel woo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S21","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":21,"global_order":95,"speaker":"TOM","english_text":"It's one unit of meaning. That's all it is.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È un'unità di significato. Tutto lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S22","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":22,"global_order":96,"speaker":"ARAN","english_text":"That's all it is. And that's the woo.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tutto lì. Ed è quello il woo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S23","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":23,"global_order":97,"speaker":"TOM","english_text":"So: not rules, not words. Something that starts and stops, and nobody knows what.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi: non regole, non parole. Qualcosa che inizia e finisce, e nessuno sa cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S24","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":24,"global_order":98,"speaker":"ARAN","english_text":"We don't know. We think.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non lo sappiamo. Lo pensiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S25","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":25,"global_order":99,"speaker":"TOM","english_text":"You said that about the fish.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"L'hai detto anche del pesce.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC04-S26","pod_slug":"method-pod-chapters","scene_number":4,"scene_label":"Chapter 4","scene_title":"Non lo so","scene_subtitle":"nobody knows how it works in the head, and \"complicated\" is the tell","difficulty":null,"sentence_number":26,"global_order":100,"speaker":"ARAN","english_text":"It was true about the fish.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Era vero anche per il pesce.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S01","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":1,"global_order":101,"speaker":"ARAN","english_text":"The moment you've got edges, you can go in lots of directions. And that's when it becomes a game.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nel momento in cui hai i collegamenti, puoi andare in tante direzioni. Ed è lì che diventa un gioco.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S02","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":2,"global_order":102,"speaker":"TOM","english_text":"So what you're saying is: control arrives before correctness.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi quello che stai dicendo è: il controllo arriva prima della correttezza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S03","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":3,"global_order":103,"speaker":"ARAN","english_text":"Yes. And sharper than that: control is what correctness grows out of. Nobody ever got correct first and then in control. — Hang on. That makes me think of the garden. Two minutes, I promise.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Sì. E ancora più preciso: il controllo è la cosa da cui cresce la correttezza. Nessuno ha mai avuto prima la correttezza e poi il controllo. — Aspetta. Questo mi fa pensare al giardino. Due minuti, promesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S04","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":4,"global_order":104,"speaker":"TOM","english_text":"Clock's running.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Il tempo corre.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S05","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":5,"global_order":105,"speaker":"ARAN","english_text":"Nobody designs a garden leaf by leaf. Nobody can. You plant, and the garden answers, and then you find out what you've actually got, which is never the thing you drew. We drew a pond. What we've got is a pond with a willow in it that nobody planted, and the willow is the best thing in the garden.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nessuno progetta un giardino foglia per foglia. Nessuno ci riesce. Tu pianti, e il giardino risponde, e poi scopri quello che hai davvero, che non è mai quello che avevi disegnato. Noi avevamo disegnato uno stagno. Quello che abbiamo è uno stagno con dentro un salice che non ha piantato nessuno, e il salice è la cosa più bella del giardino.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S06","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":6,"global_order":106,"speaker":"TOM","english_text":"One minute.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Un minuto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S07","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":7,"global_order":107,"speaker":"ARAN","english_text":"And the neighbour — this is the last bit — the neighbour has a plan. A proper plan, on paper, every bed numbered. And every year his garden looks exactly like the plan, and every year it's the most boring garden in the street, and he knows it, and he can't stop. That's a garden, not a lesson plan. Anyway — where were we?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E il vicino — questa è l'ultima cosa — il vicino ha un piano. Un piano vero, su carta, ogni aiuola numerata. E ogni anno il suo giardino è identico al piano, e ogni anno è il giardino più noioso della via, e lui lo sa, e non riesce a smettere. Quello è un giardino, non un piano di lezione. Comunque — dov'eravamo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S08","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":8,"global_order":108,"speaker":"TOM","english_text":"Control before correctness. And your garden just agreed with me.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Al controllo prima della correttezza. E il tuo giardino mi ha appena dato ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S09","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":9,"global_order":109,"speaker":"ARAN","english_text":"It always does. Three minutes?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Lo fa sempre. Tre minuti?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S10","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":10,"global_order":110,"speaker":"TOM","english_text":"Four. It was a good willow. — Do you know how I introduce your method to people?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quattro. Era un bel salice. — Sai come presento il tuo metodo alla gente?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S11","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":11,"global_order":111,"speaker":"ARAN","english_text":"Tell me.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Dimmi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S12","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":12,"global_order":112,"speaker":"TOM","english_text":"I don't explain it. I say: you're in a drama class, it's a warm-up game, and the game is called Holy Dickhead Batman. Everyone shouts every combination they can make — Holy BatHead, ManDick. Holy DickMan, BatHead. It's stupid, it's fun, by the third one everybody's laughing — and they've just learnt that a unit of meaning is a thing you can move.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Non lo spiego. Dico: sei a lezione di teatro, è un gioco di riscaldamento, e il gioco si chiama Holy Dickhead Batman. Tutti gridano ogni combinazione che riescono a fare — Holy BatHead, ManDick. Holy DickMan, BatHead. È stupido, è divertente, al terzo ridono tutti — e hanno appena imparato che un'unità di significato è una cosa che si può spostare.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S13","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":13,"global_order":113,"speaker":"ARAN","english_text":"That's it. And the thing you're giving them, without saying so, is permission.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ecco. E la cosa che gli dai, senza dirlo, è il permesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S14","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":14,"global_order":114,"speaker":"TOM","english_text":"Permission.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Il permesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S15","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":15,"global_order":115,"speaker":"ARAN","english_text":"To play. Because most of the combinations are nonsense, and that's fine. You play, and every so often one lands as a real act of communication — and you get the feedback: oh. That one worked. That's the moment. Not the correct one — the one that worked. The willow, not the plan.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Di giocare. Perché quasi tutte le combinazioni non vogliono dire niente, e va bene così. Giochi, e ogni tanto una atterra come un vero atto di comunicazione — e ti arriva il feedback: oh. Quella ha funzionato. È quello il momento. Non quella giusta — quella che ha funzionato. Il salice, non il piano.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S16","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":16,"global_order":116,"speaker":"TOM","english_text":"And then everything clicks together. Like the end of a Star Wars film.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E poi tutto si incastra. Come alla fine di un film di Guerre Stellari.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S17","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":17,"global_order":117,"speaker":"ARAN","english_text":"…In a sense.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…In un certo senso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S18","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":18,"global_order":118,"speaker":"TOM","english_text":"In what sense?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"In che senso?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC05-S19","pod_slug":"method-pod-chapters","scene_number":5,"scene_label":"Chapter 5","scene_title":"Il gioco","scene_subtitle":"control arrives before correctness, and that is when it becomes a game","difficulty":null,"sentence_number":19,"global_order":119,"speaker":"ARAN","english_text":"In the sense that nobody in a Star Wars film was ever playing.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nel senso che in un film di Guerre Stellari non gioca mai nessuno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S01","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":1,"global_order":120,"speaker":"TOM","english_text":"Every teacher on earth says the same thing. \"I'm intermediate — how do I get to fluent?\" \"Practise. Go and use it. Listen to the radio, talk to people.\"","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tutti gli insegnanti del mondo dicono la stessa cosa. «Sono a un livello intermedio — come arrivo a parlare bene?» «Fai pratica. Vai e usala. Ascolta la radio, parla con la gente.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S02","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":2,"global_order":121,"speaker":"ARAN","english_text":"And that's true.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ed è vero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S03","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":3,"global_order":122,"speaker":"TOM","english_text":"Is it?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Davvero?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S04","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":4,"global_order":123,"speaker":"ARAN","english_text":"That's true, that's right, that's exactly what you have to do — and it's incredibly painful if nobody has prepared you for it. If all you've got is a pile of words and a rule book, you walk into that room and have to invent every sentence on the spot, live. That's the cliff. But if you've already walked a thousand little paths through the words you've got, the room isn't a cliff any more. It's just more of the same.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È vero, è giusto, è esattamente quello che devi fare — ed è incredibilmente doloroso se nessuno ti ci ha preparato. Se tutto quello che hai è un mucchio di parole e un libro di regole, entri in quella stanza e devi inventarti ogni frase lì per lì, dal vivo. Quello è il precipizio. Ma se hai già percorso mille piccoli sentieri tra le parole che hai, la stanza non è più un precipizio. È solo altro dello stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S05","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":5,"global_order":124,"speaker":"TOM","english_text":"So \"go and practise\" is right, and it's the cruellest thing you can say.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi «vai a far pratica» è giusto, ed è la cosa più crudele che puoi dire.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S06","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":6,"global_order":125,"speaker":"ARAN","english_text":"Both. At the same time.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tutte e due. Nello stesso momento.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S07","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":7,"global_order":126,"speaker":"TOM","english_text":"Then give them something before the room. Films. So what you're saying is: the films are in the language they're learning, with subtitles.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora dagli qualcosa prima della stanza. I film. Quindi quello che stai dicendo è: i film sono nella lingua che stanno imparando, con i sottotitoli.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S08","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":8,"global_order":127,"speaker":"ARAN","english_text":"Nearly. Not subtitles.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quasi. Non i sottotitoli.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S09","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":9,"global_order":128,"speaker":"TOM","english_text":"What, then?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E cosa, allora?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S10","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":10,"global_order":129,"speaker":"ARAN","english_text":"Transcripts. That's not a small difference, it's the whole thing. Subtitles put the words on the screen while you're listening, so your eyes do the work and your ears go to sleep — and that's the wrong solution and it won't work. A transcript you read before. Then you listen without it, and now your ears have a ladder. Same film, completely different act. It's a path, not a cliff — that's all a transcript is.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Le trascrizioni. Non è una differenza piccola, è tutta la faccenda. I sottotitoli ti mettono le parole sullo schermo mentre ascolti, così il lavoro lo fanno gli occhi e le orecchie si addormentano — ed è la soluzione sbagliata, e non funziona. Una trascrizione la leggi prima. Poi ascolti senza, e adesso le orecchie hanno una scala. Stesso film, atto completamente diverso. È un sentiero, non un precipizio — una trascrizione è solo questo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S11","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":11,"global_order":130,"speaker":"TOM","english_text":"…Okay. So I was thinking: films for learners, with the words on the screen. You're thinking: films for everyone, and a ladder up to them for the learners.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…Va bene. Io pensavo: film per chi impara, con le parole sullo schermo. Tu pensi: film per tutti, e una scala per arrivarci, per chi impara.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S12","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":12,"global_order":131,"speaker":"ARAN","english_text":"That's it. Now you've got it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ecco. Adesso ci sei.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S13","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":13,"global_order":132,"speaker":"TOM","english_text":"But before they press play, you have to work out what they want. Their goals.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ma prima che premano play devi capire cosa vogliono. I loro obiettivi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S14","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":14,"global_order":133,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S15","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":15,"global_order":134,"speaker":"TOM","english_text":"No?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S16","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":16,"global_order":135,"speaker":"ARAN","english_text":"No. They press play. That's it. What we do is notice when they stop. They come back after a month — we noticed. So we put a few of the early sentences back in front of them. They come back the next day — we just carry on. Nobody fills in a form. Nobody has a goal. They press play, and the thing that's paying attention is us, not them.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No. Premono play. Basta. Quello che facciamo noi è accorgerci quando si fermano. Tornano dopo un mese — ce ne siamo accorti. Allora gli rimettiamo davanti qualche frase delle prime. Tornano il giorno dopo — andiamo avanti e basta. Nessuno compila un modulo. Nessuno ha un obiettivo. Premono play, e la cosa che sta attenta siamo noi, non loro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S17","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":17,"global_order":136,"speaker":"TOM","english_text":"…Okay. No form.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…Va bene. Niente modulo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S18","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":18,"global_order":137,"speaker":"ARAN","english_text":"No form. Press play.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Niente modulo. Premi play.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S19","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":19,"global_order":138,"speaker":"TOM","english_text":"Press play, walk the paths, and then the room.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Premi play, percorri i sentieri, e poi la stanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC06-S20","pod_slug":"method-pod-chapters","scene_number":6,"scene_label":"Chapter 6","scene_title":"Il precipizio","scene_subtitle":"\"go and practise\" is right, and it is the cruellest thing you can say","difficulty":null,"sentence_number":20,"global_order":139,"speaker":"ARAN","english_text":"And the room's the same thing you've been doing. In a bigger room.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E la stanza è la stessa cosa che facevi già. In una stanza più grande.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S01","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":1,"global_order":140,"speaker":"TOM","english_text":"Schools. How would you do it in a school?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Le scuole. Come lo faresti in una scuola?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S02","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":2,"global_order":141,"speaker":"ARAN","english_text":"It's been a long time since I've worked in schools. I'm out of practice, and I haven't thought about it much.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È da tanto tempo che non lavoro nelle scuole. Sono fuori allenamento, e non ci ho pensato molto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S03","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":3,"global_order":142,"speaker":"TOM","english_text":"But?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Però?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S04","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":4,"global_order":143,"speaker":"ARAN","english_text":"But if you give me one roll of the dice — one day a week. One whole day, every week, for a year. Not an hour on Tuesday and an hour on Thursday — one day, so the paths get walked before they've been forgotten. That's what I'd want to test, and I'd bet on it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Però se mi dai un solo tiro di dadi — un giorno alla settimana. Un giorno intero, ogni settimana, per un anno. Non un'ora il martedì e un'ora il giovedì — un giorno, così i sentieri li percorrono prima di averli dimenticati. È quello che vorrei provare, e ci scommetterei.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S05","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":5,"global_order":144,"speaker":"TOM","english_text":"That's a big bite out of the timetable.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È un bel morso all'orario.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S06","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":6,"global_order":145,"speaker":"ARAN","english_text":"It looks big. But I suspect you wouldn't even need the whole year. And I'll tell you what they'd get back. You know what breaks my heart? Go into any school. Find the kids who actually care — the ones making an effort — and open their workbooks. Highlighter. Page after page of highlighter. And the results are in: highlighting makes zero difference. Worse than zero — it costs them the time.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Sembra grande. Ma sospetto che non servirebbe nemmeno l'anno intero. E ti dico cosa ci guadagnerebbero. Sai cosa mi spacca il cuore? Entra in una scuola qualsiasi. Trova i ragazzi a cui importa davvero — quelli che si impegnano — e apri i loro quaderni. Evidenziatore. Pagine e pagine di evidenziatore. E i risultati ci sono: evidenziare non fa nessuna differenza. Peggio di nessuna — gli costa il tempo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S07","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":7,"global_order":146,"speaker":"TOM","english_text":"And gives nothing back.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E non rende niente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S08","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":8,"global_order":147,"speaker":"ARAN","english_text":"Nothing. Nobody told them how a memory is made. Somebody, once, told them \"learn it\", and an older brother had a highlighter, so they're breaking their backs doing the one thing that's been shown not to work. And we let them. That's not their failure. That's ours.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Niente. Nessuno gli ha detto come si forma una memoria. Qualcuno, una volta, gli ha detto «imparalo», e un fratello più grande aveva un evidenziatore, e così si spaccano la schiena a fare l'unica cosa che è dimostrato che non funziona. E noi glielo lasciamo fare. Non è un fallimento loro. È nostro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S09","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":9,"global_order":148,"speaker":"TOM","english_text":"Ours.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nostro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S10","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":10,"global_order":149,"speaker":"ARAN","english_text":"Ours. We're the generation that went through it and found out. Saying so is the job.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nostro. Siamo la generazione che ci è passata e l'ha scoperto. Dirlo è il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S11","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":11,"global_order":150,"speaker":"TOM","english_text":"Then that's the first thing we say. Before the method. Before anything.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora è la prima cosa che diciamo. Prima del metodo. Prima di tutto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S12","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":12,"global_order":151,"speaker":"ARAN","english_text":"Before anything.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Prima di tutto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S13","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":13,"global_order":152,"speaker":"TOM","english_text":"And the day a week — for how long? How much time is it going to take?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E il giorno alla settimana — per quanto? Quanto tempo ci vorrà?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S14","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":14,"global_order":153,"speaker":"ARAN","english_text":"A lot.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tanto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S15","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":15,"global_order":154,"speaker":"TOM","english_text":"How much? Ten hours?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quanto? Dieci ore?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S16","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":16,"global_order":155,"speaker":"ARAN","english_text":"More. Ten hours — and then ten more.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Di più. Dieci ore — e poi altre dieci.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S17","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":17,"global_order":156,"speaker":"TOM","english_text":"And then?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E poi?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S18","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":18,"global_order":157,"speaker":"ARAN","english_text":"And then ten more. And then ten more.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E poi altre dieci. E poi altre dieci.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S19","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":19,"global_order":158,"speaker":"TOM","english_text":"So how much altogether? A hundred?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindi quanto in tutto? Cento?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S20","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":20,"global_order":159,"speaker":"ARAN","english_text":"A hundred hours. It's a hundred hours. Ten hours, and then ten more, and then ten more — a hundred hours. Take them as you want.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Cento ore. Sono cento ore. Dieci ore, e poi altre dieci, e poi altre dieci — cento ore. Prendile come vuoi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S21","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":21,"global_order":160,"speaker":"TOM","english_text":"Then I'll take them like this. Thirteen weeks. One full day to start, then two hours a week for eleven weeks, then one full day to close. That would probably be plenty.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora le prendo così. Tredici settimane. Un giorno pieno per iniziare, poi due ore alla settimana per undici settimane, poi un giorno pieno per chiudere. Probabilmente basterebbe.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S22","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":22,"global_order":161,"speaker":"ARAN","english_text":"Mm. I'd be inclined not to differentiate that much. Here's the model: five days, then a year of an hour or two a week, then five days again. With your thirteen weeks you'd surprise a few people. And you'd lose a few.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Mm. Io sarei propenso a non differenziare così tanto. Il modello è questo: cinque giorni, poi un anno di un'ora o due alla settimana, poi altri cinque giorni. Con le tue tredici settimane qualcuno lo sorprenderesti. E qualcuno lo perderesti.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S23","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":23,"global_order":162,"speaker":"TOM","english_text":"Fewer than you think.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Meno di quanto pensi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S24","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":24,"global_order":163,"speaker":"ARAN","english_text":"Maybe. But one day, twelve weeks, one day — some of them will hear that and think it isn't enough to be worth doing. To me the risk doesn't seem worth it. Five days.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Può darsi. Ma un giorno, dodici settimane, un giorno — qualcuno lo sentirà e penserà che non basta per valerne la pena. A me il rischio non sembra valerne la pena. Cinque giorni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S25","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":25,"global_order":164,"speaker":"TOM","english_text":"And I still like my thirteen weeks.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"E a me piacciono ancora le mie tredici settimane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S26","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":26,"global_order":165,"speaker":"ARAN","english_text":"I know. And I still don't.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Lo so. E a me continuano a non piacere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S27","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":27,"global_order":166,"speaker":"TOM","english_text":"Then we'll put it on pause. Okay.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora la mettiamo in pausa. Va bene.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC07-S28","pod_slug":"method-pod-chapters","scene_number":7,"scene_label":"Chapter 7","scene_title":"Un tiro di dadi","scene_subtitle":"how you would do it in a school, and how long it takes","difficulty":null,"sentence_number":28,"global_order":167,"speaker":"ARAN","english_text":"On pause. A hundred hours either way.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"In pausa. Cento ore in ogni caso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S01","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":1,"global_order":168,"speaker":"TOM","english_text":"There's a school that wants you. Five days, a group of twelve. Will you do it?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"C'è una scuola che ti vuole. Cinque giorni, un gruppo di dodici. Lo fai?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S02","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":2,"global_order":169,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S03","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":3,"global_order":170,"speaker":"TOM","english_text":"No?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S04","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":4,"global_order":171,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S05","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":5,"global_order":172,"speaker":"TOM","english_text":"Not even for a week? They're keen. They'd pay properly.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Nemmeno per una settimana? Ci tengono. Pagano bene.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S06","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":6,"global_order":173,"speaker":"ARAN","english_text":"No. One to one. That's all I say yes to now.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"No. Uno a uno. È l'unica cosa a cui dico di sì, ormai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S07","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":7,"global_order":174,"speaker":"TOM","english_text":"Since when?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Da quando?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S08","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":8,"global_order":175,"speaker":"ARAN","english_text":"Since I understood what a group can do to a week. One to one, I know it works — whoever they are, whatever the room, we get there. A group — four people in a bed and breakfast for five days, one of them has two bad days, and all of it lands on the other three. I'd need to know who's in the room before I said yes, and I never do. So: no.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Da quando ho capito cosa può fare un gruppo a una settimana. Uno a uno, so che funziona — chiunque sia, qualunque sia la stanza, ci arriviamo. Un gruppo — quattro persone in un bed and breakfast per cinque giorni, uno di loro ha due giornate storte, e tutto cade addosso agli altri tre. Dovrei sapere chi c'è nella stanza prima di dire sì, e non lo so mai. Quindi: no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S09","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":9,"global_order":176,"speaker":"TOM","english_text":"Two bad days.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Due giornate storte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S10","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":10,"global_order":177,"speaker":"ARAN","english_text":"Two bad days. I've watched it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Due giornate storte. L'ho visto succedere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S11","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":11,"global_order":178,"speaker":"TOM","english_text":"Tell me.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-09-03T23:24:14.229017+00:00","variant_key":null,"target_text":"Dimmi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S12","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":12,"global_order":179,"speaker":"ARAN","english_text":"I had one group with one truly negative person in it. And the most positive person in the room — the one you'd want in every group — paired up with her. On purpose. Good intentions: he was going to bring her round. And by the end of the day he'd become exactly as negative as she was. Not her better. Him worse.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ho avuto un gruppo con dentro una persona davvero negativa. E la persona più positiva della stanza — quella che vorresti in ogni gruppo — si è messa in coppia con lei. Apposta. Buone intenzioni: la avrebbe tirata su. E alla fine della giornata lui era diventato esattamente negativo quanto lei. Non lei meglio. Lui peggio.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S13","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":13,"global_order":180,"speaker":"TOM","english_text":"That's literally how cancer works.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È letteralmente così che funziona il cancro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S14","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":14,"global_order":181,"speaker":"ARAN","english_text":"Exactly.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Esatto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S15","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":15,"global_order":182,"speaker":"TOM","english_text":"One cell, and the healthy one next to it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Una cellula, e quella sana lì accanto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S16","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":16,"global_order":183,"speaker":"ARAN","english_text":"Exactly that. And nonetheless — that's the challenge, not the verdict. The group dynamic. Because if you solve for the dynamic, you've got something that's orders of magnitude more powerful than one person alone. It's just that \"solve for the dynamic\" is the whole job.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Esatto, proprio così. E ciò nonostante — quella è la sfida, non il verdetto. La dinamica del gruppo. Perché se risolvi la dinamica, hai una cosa più potente di ordini di grandezza rispetto a una persona da sola. È solo che «risolvere la dinamica» è tutto il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S17","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":17,"global_order":184,"speaker":"TOM","english_text":"Then it's the whole job.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Allora è tutto il lavoro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S18","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":18,"global_order":185,"speaker":"ARAN","english_text":"The whole job. And nobody's done it.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Tutto il lavoro. E non l'ha fatto nessuno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S19","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":19,"global_order":186,"speaker":"TOM","english_text":"I've got one too. A few years ago we had a group — brilliant people. We wanted to grow food for the whole street. And I'll say it before you do: it proves nothing. Accept it anyway.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ne ho una anch'io. Qualche anno fa avevamo un gruppo — gente in gamba. Volevamo coltivare cibo per tutta la via. E lo dico prima che lo dica tu: non dimostra niente. Accettala lo stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S20","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":20,"global_order":187,"speaker":"ARAN","english_text":"That's my line.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quella è una battuta mia.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S21","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":21,"global_order":188,"speaker":"TOM","english_text":"It's your line. You said it two hours ago about a learner and a letter, and you said it years ago, in the middle of something else entirely, and you said it exactly like this: I lost my foot in that river—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"È una battuta tua. L'hai detta due ore fa su una studentessa e una lettera, e l'hai detta anni fa, nel mezzo di tutt'altro discorso, e l'hai detta proprio così: ho perso il piede in quel fiume—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S22","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":22,"global_order":189,"speaker":"ARAN","english_text":"—please accept my anecdotal evidence. Yes. The crocodile. Though by now it's yours too.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"— ti prego, accetta la mia prova aneddotica. Sì. Il coccodrillo. Anche se ormai è anche tua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S23","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":23,"global_order":190,"speaker":"TOM","english_text":"It is now.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Adesso sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S24","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":24,"global_order":191,"speaker":"ARAN","english_text":"A good line ends up belonging to both. Like everything else in a long conversation — after a while you stop knowing who brought what. Go on. The street.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Una bella battuta finisce per appartenere a tutti e due. Come tutto il resto, in una conversazione lunga — dopo un po' non sai più chi ha portato cosa. Vai. La via.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S25","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":25,"global_order":192,"speaker":"TOM","english_text":"Brilliant people. Food for the whole street.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Gente in gamba. Cibo per tutta la via.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S26","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":26,"global_order":193,"speaker":"ARAN","english_text":"Sounds fantastic. And what happened to that group?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Sembra fantastico. E che fine ha fatto, quel gruppo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S27","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":27,"global_order":194,"speaker":"TOM","english_text":"…It's gone cold.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"…Si è raffreddato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S28","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":28,"global_order":195,"speaker":"ARAN","english_text":"How many of you were there?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quanti eravate?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S29","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":29,"global_order":196,"speaker":"TOM","english_text":"Fifteen. We did a design day, we made a ten-year plan. All of them busy. All of them time-poor.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Quindici. Abbiamo fatto una giornata di progettazione, abbiamo fatto un piano di dieci anni. Tutti impegnati. Tutti poveri di tempo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S30","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":30,"global_order":197,"speaker":"ARAN","english_text":"There's your answer. Fifteen people in a whole street, and every one of them without time. It wasn't the idea that failed — there just aren't many people with time. There never are, anywhere. That's the other thing a group does: it finds the one hour a week that fifteen people don't have.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Ecco la risposta. Quindici persone in tutta una via, e nessuna di loro con tempo. Non è stata l'idea a fallire — è che non c'è tanta gente che ha tempo. Non c'è mai, da nessuna parte. È l'altra cosa che fa un gruppo: trova l'ora alla settimana che quindici persone non hanno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S31","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":31,"global_order":198,"speaker":"TOM","english_text":"And yet you'd do it again. Learning with other people — it's not a course. It's flexible; you decide together where you're going; it's temporary; and at the end, the thing you've made lives between you and the road. It's not a course. It's a trip in—","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Eppure lo rifaresti. Imparare con altre persone — non è un corso. È flessibile; decidete insieme dove andare; è temporaneo; e alla fine, quello che avete creato vive tra voi e la strada. Non è un corso. È un viaggio in—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S32","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":32,"global_order":199,"speaker":"ARAN","english_text":"—a car. Yes. I like the road trip. And it goes wider than that.","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"—macchina. Sì. Mi piace, il viaggio in macchina. E va anche più in là.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S33","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":33,"global_order":200,"speaker":"TOM","english_text":"Wider how?","author_notes":null,"created_at":"2026-08-30T19:35:31.86291+00:00","updated_at":"2026-08-30T19:35:31.86291+00:00","variant_key":null,"target_text":"Più in là come?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S34","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":34,"global_order":201,"speaker":"ARAN","english_text":"You'll do more than one. Sometimes with the same people, sometimes with new ones. A tour. And there will be crashes — that's the part you actually learn from. The negative woman was a crash. I learnt one to one from her.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ne farai più di uno. A volte con le stesse persone, a volte con gente nuova. Un tour. E ci saranno degli incidenti — ed è da lì che impari davvero. La signora negativa era un incidente. Da lei ho imparato l'uno a uno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S35","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":35,"global_order":202,"speaker":"TOM","english_text":"Now you're driving my metaphor.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Adesso la mia metafora la stai guidando tu.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S36","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":36,"global_order":203,"speaker":"ARAN","english_text":"You gave me the keys.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Mi hai dato tu le chiavi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S37","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":37,"global_order":204,"speaker":"TOM","english_text":"Keep them.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Tienile.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S38","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":38,"global_order":205,"speaker":"ARAN","english_text":"Which is why the evening class never works, and it's three things. One: it's short on edges — it's your buildings in the field, a word a week and no streets. Two: it's short on repetition — once a week, and by the next week the curve has had it. And the third thing — and this is the important one — is that when you actually—","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ed è per questo che il corso serale non funziona mai, e sono tre cose. Uno: è povero di collegamenti — sono i tuoi palazzi in mezzo al campo, una parola alla settimana e niente strade. Due: è povero di ripetizione — una volta alla settimana, e la settimana dopo la curva se l'è già mangiata. E la terza cosa — ed è quella importante — è che quando tu davvero—","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S39","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":39,"global_order":206,"speaker":"TOM","english_text":"Hang on. The dog.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Aspetta. Il cane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S40","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":40,"global_order":207,"speaker":"ARAN","english_text":"The dog?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Il cane?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S41","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":41,"global_order":208,"speaker":"TOM","english_text":"The dog has opinions. Someone's at the door, and the dog has views about the door, and about the person behind it. This will take a while.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Il cane ha delle opinioni. C'è qualcuno alla porta, e il cane ha le sue idee sulla porta, e su chi c'è dietro. Ci vorrà un po'.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S42","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":42,"global_order":209,"speaker":"ARAN","english_text":"Fine. We'll pick this up next time — you owe me a third thing. When? Are you free on Tuesday?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Va bene. Riprendiamo la prossima volta — mi devi una terza cosa. Quando? Sei libero martedì?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S43","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":43,"global_order":210,"speaker":"TOM","english_text":"Tuesday, no. I have something on Tuesday.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Martedì no. Martedì ho un impegno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S44","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":44,"global_order":211,"speaker":"ARAN","english_text":"Thursday, then?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Giovedì, allora?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S45","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":45,"global_order":212,"speaker":"TOM","english_text":"Thursday I'm not here.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Giovedì non ci sono.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S46","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":46,"global_order":213,"speaker":"ARAN","english_text":"…Tomorrow.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"…Domani.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S47","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":47,"global_order":214,"speaker":"TOM","english_text":"Tomorrow?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Domani?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S48","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":48,"global_order":215,"speaker":"ARAN","english_text":"Tomorrow. I'll be there at two.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Domani. Sono lì alle due.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC08-S49","pod_slug":"method-pod-chapters","scene_number":8,"scene_label":"Chapter 8","scene_title":"Uno a uno","scene_subtitle":"what a group does to a week, and why it is still worth doing","difficulty":null,"sentence_number":49,"global_order":216,"speaker":"TOM","english_text":"Tomorrow. At two. Four hours going, four hours going home, for two hours of talking with me. …Okay. Tomorrow at two. I'll be here. Noted. The third thing, tomorrow.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Domani. Alle due. Quattro ore per venire, quattro ore per tornare, per due ore di chiacchiere con me. …Va bene. Domani alle due. Io sono qui. Segnato. La terza cosa, domani.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S01","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":1,"global_order":217,"speaker":"TOM","english_text":"Before anything else. You owed me a third thing.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Prima di tutto il resto. Mi dovevi una terza cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S02","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":2,"global_order":218,"speaker":"ARAN","english_text":"I owed you a third thing.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ti dovevo una terza cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S03","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":3,"global_order":219,"speaker":"TOM","english_text":"The dog. You said \"the third thing, and this is the important one, is that when you actually—\" and then the dog.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Il cane. Hai detto «la terza cosa, ed è quella importante, è che quando tu davvero—» e poi il cane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S04","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":4,"global_order":220,"speaker":"ARAN","english_text":"And then the dog. …I've lost it.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"E poi il cane. …L'ho persa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S05","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":5,"global_order":221,"speaker":"TOM","english_text":"You've lost the important one.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Hai perso quella importante.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S06","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":6,"global_order":222,"speaker":"ARAN","english_text":"I've lost the important one. I don't know what it was. Give me the first two.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ho perso quella importante. Non so cos'era. Dammi le prime due.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S07","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":7,"global_order":223,"speaker":"TOM","english_text":"One: the evening class is short on edges — that's the building in the middle of the field, you gave it me in the first hour, a word a week and no streets. Two: it's short on repetition — once a week and the curve has had it, that's the fish, the one you wouldn't let me keep. Three: \"when you actually—\"","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Uno: il corso serale è povero di collegamenti — è il palazzo in mezzo al campo, me l'hai dato tu nella prima ora, una parola alla settimana e niente strade. Due: è povero di ripetizione — una volta alla settimana e la curva se l'è mangiata, è il pesce, quello che non mi hai lasciato tenere. Tre: «quando tu davvero—»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S08","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":8,"global_order":224,"speaker":"ARAN","english_text":"—go and use it. Yes. That's it. When you actually go and use it — if you've already walked the paths, it isn't a step-change any more. It's the same thing you've been doing, in a bigger room. That's the third thing. That's the whole reason it works, and it's the one the evening class can't give you, because it never walked you anywhere.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"—vai a usarla. Sì. È quella. Quando vai davvero a usarla — se hai già percorso i sentieri, non è più un salto. È la stessa cosa che facevi già, in una stanza più grande. Questa è la terza cosa. È tutto il motivo per cui funziona, ed è quella che il corso serale non ti può dare, perché non ti ha mai fatto camminare da nessuna parte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S09","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":9,"global_order":225,"speaker":"TOM","english_text":"The bigger room. You said that before the dog too — before the films. The cliff.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"La stanza più grande. L'avevi detta anche prima del cane — prima dei film. Il precipizio.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S10","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":10,"global_order":226,"speaker":"ARAN","english_text":"Then I've said it three times.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora l'ho detta tre volte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S11","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":11,"global_order":227,"speaker":"TOM","english_text":"Everything in this conversation gets said three times.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"In questa conversazione tutto viene detto tre volte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S12","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":12,"global_order":228,"speaker":"ARAN","english_text":"That's the method. Debt paid?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"È il metodo. Debito saldato?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S13","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":13,"global_order":229,"speaker":"TOM","english_text":"Debt paid.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Debito saldato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC09-S14","pod_slug":"method-pod-chapters","scene_number":9,"scene_label":"Chapter 9","scene_title":"La terza cosa","scene_subtitle":"why the evening class fails: three things, one of them lost and rebuilt","difficulty":null,"sentence_number":14,"global_order":230,"speaker":"ARAN","english_text":"Debt paid. Never let a dog near the important one.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Debito saldato. Mai lasciare un cane vicino a quella importante.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S01","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":1,"global_order":231,"speaker":"ARAN","english_text":"How did you find it? When? Where? How much time, every day? How often? — There's a lot there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Come l'hai trovato? Quando? Dove? Quanto tempo, ogni giorno? Quanto spesso? — C'è tanta roba, lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S02","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":2,"global_order":232,"speaker":"TOM","english_text":"Yes.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S03","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":3,"global_order":233,"speaker":"ARAN","english_text":"There is, isn't there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Eh, sì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S04","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":4,"global_order":234,"speaker":"TOM","english_text":"Yes. A lot. So — first, how. Then when. Then how much, and how often. And after that you can say: but is it good? And I say: I talk. That's all.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Sì. Tanta. Allora — prima il come. Poi il quando. Poi il quanto, e il quanto spesso. E dopo puoi dire: ma è buono? E io dico: parlo. Tutto qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S05","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":5,"global_order":235,"speaker":"ARAN","english_text":"Start with how.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Comincia dal come.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S06","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":6,"global_order":236,"speaker":"TOM","english_text":"How: I did a day of Mandarin last summer. One day. And another this year — different words, different structures, because you'd changed it all in between, obviously. And by the end of that second day I was thinking in Chinese. Not well. But it felt like more than a month of hard work would have given me, and I've done the month, in other languages, and I know what it buys.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Il come: l'estate scorsa ho fatto un giorno di cinese. Un giorno. E un altro quest'anno — parole diverse, strutture diverse, perché nel frattempo avevi cambiato tutto, ovviamente. E alla fine di quel secondo giorno pensavo in cinese. Non bene. Ma sembrava più di quello che mi avrebbe dato un mese di lavoro duro, e il mese l'ho fatto, in altre lingue, e so cosa compra.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S07","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":7,"global_order":237,"speaker":"ARAN","english_text":"Two days, a year apart.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Due giorni, a un anno di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S08","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":8,"global_order":238,"speaker":"TOM","english_text":"A year apart.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"A un anno di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S09","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":9,"global_order":239,"speaker":"ARAN","english_text":"I've got mine on film. Manx — a conversation with a native speaker after day one, and another after day two, sixteen months later. Day one: fine, pleased with myself, not bad. Day two: the first real intimation of \"I can do this\" — still small, still a couple of hundred words, nowhere near seven hundred, but I could pick most of them up and turn them round. Something was going on.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"I miei ce li ho filmati. Manx — una conversazione con un madrelingua dopo il primo giorno, e un'altra dopo il secondo, sedici mesi dopo. Primo giorno: bene, contento di me, niente male. Secondo giorno: la prima vera avvisaglia di «ce la posso fare» — ancora piccola, ancora un paio di centinaia di parole, lontanissimo da settecento, ma quasi tutte le sapevo tirare fuori e girare. Stava succedendo qualcosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S10","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":10,"global_order":240,"speaker":"TOM","english_text":"Sixteen months apart.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"A sedici mesi di distanza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S11","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":11,"global_order":241,"speaker":"ARAN","english_text":"Two days. And you don't need the third one to know.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Due giorni. E non ti serve il terzo per saperlo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S12","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":12,"global_order":242,"speaker":"TOM","english_text":"You waited sixteen months to test one word? You're mad.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Hai aspettato sedici mesi per testare una parola? Sei matto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S13","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":13,"global_order":243,"speaker":"ARAN","english_text":"Sixteen months, yes. And since you've just called me mad —","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Sedici mesi, sì. E visto che mi hai appena dato del matto —","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S14","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":14,"global_order":244,"speaker":"TOM","english_text":"Oh no.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Oh no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S15","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":15,"global_order":245,"speaker":"ARAN","english_text":"— you tested yourself in Chinese for a whole day. For fun. Nobody asked you to. You told me about it afterwards, and you were proud of it. And then you did it again, a year later, to see if the first one was still there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"— tu ti sei messo alla prova in cinese per un giorno intero. Per divertimento. Nessuno te l'aveva chiesto. Me l'hai raccontato dopo, ed eri pure fiero. E poi l'hai rifatto, un anno dopo, per vedere se il primo c'era ancora.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S16","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":16,"global_order":246,"speaker":"TOM","english_text":"…No, you're completely right.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"…No, hai perfettamente ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S17","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":17,"global_order":247,"speaker":"ARAN","english_text":"Mad, both of us. That's why it works. Day one. Then day two. And after day two — no more. That was all.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Matti, tutti e due. È per questo che funziona. Giorno uno. Poi giorno due. E dopo il giorno due — basta. Basta così.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S18","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":18,"global_order":248,"speaker":"TOM","english_text":"For two years.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Per due anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S19","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":19,"global_order":249,"speaker":"ARAN","english_text":"Three. Not two — three years.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Tre. Non due — tre anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S20","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":20,"global_order":250,"speaker":"TOM","english_text":"Three years. And it's still there?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Tre anni. Ed è ancora lì?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S21","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":21,"global_order":251,"speaker":"ARAN","english_text":"Still there. Not all of it. But I can say it — slowly, today, but I can say it. Day one, day two, three years — and it's still there. That's what I want people to see.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ancora lì. Non tutto. Ma lo so dire — piano, oggi, ma lo so dire. Giorno uno, giorno due, tre anni — ed è ancora lì. È questo che voglio far vedere alla gente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S22","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":22,"global_order":252,"speaker":"TOM","english_text":"Three years. — There's a fixed number of atoms on the planet. We're not losing atoms of water. You didn't lose the Manx. It's just somewhere you haven't been for three years.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Tre anni. — Sul pianeta c'è un numero fisso di atomi. Non stiamo perdendo atomi d'acqua. Il manx non l'hai perso. È solo in un posto dove non vai da tre anni.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S23","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":23,"global_order":253,"speaker":"ARAN","english_text":"Somewhere I haven't been. — I have never once in my life thought: I want to learn Manx. Never. And I've done two days of it now — because it was an experiment, and there was a man willing to make the material, and I wanted to test some things. And now I've got unfinished business. I'm going to learn more Manx. I don't know if I'll ever be properly conversational in it — I really don't — but I'm going to learn more.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Un posto dove non vado. — In vita mia non ho mai pensato, nemmeno una volta: voglio imparare il manx. Mai. E adesso ne ho fatti due giorni — perché era un esperimento, e c'era uno disposto a fare il materiale, e volevo testare delle cose. E adesso ho un conto in sospeso. Imparerò altro manx. Non so se arriverò mai a parlarlo davvero — non lo so proprio — ma ne imparerò altro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S24","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":24,"global_order":254,"speaker":"TOM","english_text":"You don't know if you'll get there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non sai se ci arriverai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S25","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":25,"global_order":255,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S26","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":26,"global_order":256,"speaker":"TOM","english_text":"No. …That's allowed. Unfinished business is a good reason. Better than most.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"No. …È permesso. Un conto in sospeso è una buona ragione. Meglio di quasi tutte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S27","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":27,"global_order":257,"speaker":"ARAN","english_text":"It's the only reason I've ever actually needed.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"È l'unica ragione di cui abbia mai avuto davvero bisogno.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S28","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":28,"global_order":258,"speaker":"TOM","english_text":"Then learn more Manx. So when's day three?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora impara altro manx. Allora, il terzo giorno quand'è?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S29","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":29,"global_order":259,"speaker":"ARAN","english_text":"…That's on me. I've been waiting. I told myself I needed fifteen new dialogues for a day, and I haven't got fifteen, and I've sat on that for a year as if it were a reason. It isn't. It's an excuse with a number on it. I've got seven, maybe eight — enough for half a day. So I stop waiting, and do the half day, and the half day is the price of having waited.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"…Questa è colpa mia. Sono stato ad aspettare. Mi ero detto che per un giorno mi servivano quindici dialoghi nuovi, e quindici non ce li ho, e ci sono rimasto seduto sopra per un anno come se fosse una ragione. Non lo è. È una scusa con un numero attaccato. Ne ho sette, forse otto — bastano per mezza giornata. Quindi smetto di aspettare, e faccio la mezza giornata, e la mezza giornata è il prezzo di aver aspettato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S30","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":30,"global_order":260,"speaker":"TOM","english_text":"Half a day.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Mezza giornata.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S31","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":31,"global_order":261,"speaker":"ARAN","english_text":"Half a day. With the seven.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Mezza giornata. Con i sette.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S32","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":32,"global_order":262,"speaker":"TOM","english_text":"Then that's day three. Nobody said days come in one size.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora è quello il terzo giorno. Nessuno ha detto che i giorni vengono in una taglia sola.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S33","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":33,"global_order":263,"speaker":"ARAN","english_text":"Nobody did. I did.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Nessuno. L'ho detto io.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC10-S34","pod_slug":"method-pod-chapters","scene_number":10,"scene_label":"Chapter 10","scene_title":"Due giorni","scene_subtitle":"what two days a year apart actually show","difficulty":null,"sentence_number":34,"global_order":264,"speaker":"TOM","english_text":"Then un-say it. Half a day, and the atoms are still there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora ritiralo. Mezza giornata, e gli atomi sono ancora lì.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S01","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":1,"global_order":265,"speaker":"TOM","english_text":"But where does a bank get the money for a mortgage?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ma dove li prende, una banca, i soldi per un mutuo?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S02","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":2,"global_order":266,"speaker":"ARAN","english_text":"It doesn't. Watch — I'll be the bank, you be you. You come in, you sit down, and you say it: \"I'd like a mortgage.\" Go on.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-09-03T23:24:14.06838+00:00","variant_key":null,"target_text":"Non li prende. Guarda — io faccio la banca, tu fai te. Tu entri, ti siedi, e dici: «Vorrei un mutuo». Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S03","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":3,"global_order":267,"speaker":"TOM","english_text":"\"I'd like a mortgage.\"","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"«Vorrei un mutuo».","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S04","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":4,"global_order":268,"speaker":"ARAN","english_text":"And the bank says: \"Of course. One moment.\" And it invents the money. There. Now it exists. A second ago it didn't exist, and it didn't come out of anybody else's account.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"E la banca dice: «Certo. Un momento». E inventa i soldi. Ecco. Adesso esistono. Un secondo fa non esistevano, e non sono usciti dal conto di nessun altro.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S05","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":5,"global_order":269,"speaker":"TOM","english_text":"It doesn't take it from anywhere?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non li prende da nessuna parte?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S06","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":6,"global_order":270,"speaker":"ARAN","english_text":"From nowhere. A magic wand. That's why it's a power.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Da nessuna parte. Una bacchetta magica. È per questo che è un potere.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S07","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":7,"global_order":271,"speaker":"TOM","english_text":"And then it goes round, and at the end of the month everybody wants you to pay it back.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"E poi girano, e a fine mese tutti vogliono che tu glieli ripaghi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S08","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":8,"global_order":272,"speaker":"ARAN","english_text":"…and at the end of the month everybody wants you to pay it back. Hang on — what did you say, an hour ago? About the Manx. There's a fixed number of atoms on the planet.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"…e a fine mese tutti vogliono che tu glieli ripaghi. Aspetta — cos'hai detto, un'ora fa? Sul manx. Sul pianeta c'è un numero fisso di atomi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S09","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":9,"global_order":273,"speaker":"TOM","english_text":"We're not losing atoms of water.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non stiamo perdendo atomi d'acqua.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S10","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":10,"global_order":274,"speaker":"ARAN","english_text":"We're not losing atoms of water. So it's like atoms, isn't it. You make this much currency, it moves round all month, and at the end of the month it's all still here — it's just in the shops. You haven't lost any of it. You only have to know where it went. Same as the Manx. It's in a place you haven't been.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non stiamo perdendo atomi d'acqua. Quindi è come gli atomi, no? Fai questa quantità di moneta, gira per tutto il mese, e a fine mese è ancora tutta qui — è solo nei negozi. Non ne hai persa nemmeno un po'. Devi solo sapere dov'è andata. Come il manx. È in un posto dove non sei andato.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S11","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":11,"global_order":275,"speaker":"TOM","english_text":"You've been saving that up.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Te la tenevi da parte.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S12","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":12,"global_order":276,"speaker":"ARAN","english_text":"Since you said it. I was waiting for it to come round.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Da quando l'hai detta. Aspettavo che tornasse il momento.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S13","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":13,"global_order":277,"speaker":"TOM","english_text":"Good callback.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Bel richiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S14","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":14,"global_order":278,"speaker":"ARAN","english_text":"Your atoms. I just gave them somewhere to go. And it's the same disaster with IP, from the other side —","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Sono i tuoi atomi. Io gli ho solo dato un posto dove andare. Ed è lo stesso disastro con la proprietà intellettuale, visto dall'altra parte —","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S15","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":15,"global_order":279,"speaker":"TOM","english_text":"Go on.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Vai.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S16","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":16,"global_order":280,"speaker":"ARAN","english_text":"IP is: I'm going to build something that would help every human alive, and then I'm going to stop humans using it. Atoms with a wall round them. — Hang on. This is real time: an email, just now, from the people thinking of investing in us. \"We'll need details of your IP. We need to know there's IP before we can invest.\"","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"La proprietà intellettuale è: costruisco una cosa che aiuterebbe ogni essere umano vivo, e poi impedisco agli esseri umani di usarla. Atomi con un muro intorno. — Aspetta. Questo è in diretta: un'email, adesso, dalle persone che stanno pensando di investire in noi. «Ci serviranno i dettagli della vostra proprietà intellettuale. Dobbiamo sapere che c'è, prima di investire.»","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S17","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":17,"global_order":281,"speaker":"TOM","english_text":"Of course they do.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Per forza.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S18","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":18,"global_order":282,"speaker":"ARAN","english_text":"And I'm sitting here typing: yes, we've got IP, loads of it. Because we have.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"E io sono qui che scrivo: sì, ce l'abbiamo, un sacco. Perché ce l'abbiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S19","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":19,"global_order":283,"speaker":"TOM","english_text":"So. Horizon one. We are where we are, and we start where we are. You'd like to think in ideas and not worry about the rest, and so would I — and we both still need to eat. The bank invented the money; somebody still has to pay it back at the end of the month. That's us.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ecco. Orizzonte uno. Siamo dove siamo, e partiamo da dove siamo. Ti piacerebbe pensare solo a idee e non preoccuparti del resto, e piacerebbe anche a me — e tutti e due dobbiamo ancora mangiare. La banca i soldi li ha inventati; a fine mese qualcuno li deve ripagare lo stesso. Siamo noi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S20","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":20,"global_order":284,"speaker":"ARAN","english_text":"We both still need to eat. Right — where was I. Walls round atoms.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Tutti e due dobbiamo ancora mangiare. Bene — dov'ero rimasto. Muri intorno agli atomi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC11-S21","pod_slug":"method-pod-chapters","scene_number":11,"scene_label":"Chapter 11","scene_title":"I soldi","scene_subtitle":"value is invented, and then it is never lost, only moved","difficulty":null,"sentence_number":21,"global_order":285,"speaker":"TOM","english_text":"Walls round atoms. And the atoms are all still here.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Muri intorno agli atomi. E gli atomi sono tutti ancora qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S01","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":1,"global_order":286,"speaker":"TOM","english_text":"Here's what I actually want. Ten languages, in parallel, one day a year each. Three years, and I'm speaking all ten — badly, and happily. Minimum total effort. That's the only thing I care about.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ecco cosa voglio davvero. Dieci lingue, in parallelo, un giorno all'anno ciascuna. Tre anni, e le parlo tutte e dieci — male, e felice. Minimo sforzo totale. È l'unica cosa che mi interessa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S02","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":2,"global_order":287,"speaker":"ARAN","english_text":"No. You care about efficiency until you need something. You need Chinese by October. So one day a year for ten years isn't going to win — you dive in and hammer at it, seventy-five dialogues in ten days, and you don't care what it costs. Efficiency is lovely. But so is speed, and speed is the one that answers to a date.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"No. Ti interessa l'efficienza finché non ti serve qualcosa. Ti serve il cinese per ottobre. Quindi un giorno all'anno per dieci anni non vince — ti butti dentro e ci martelli sopra, settantacinque dialoghi in dieci giorni, e non ti importa quanto costa. L'efficienza è bellissima. Ma lo è anche la velocità, e la velocità è quella che risponde a una data.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S03","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":3,"global_order":288,"speaker":"TOM","english_text":"Speed is a feeling. Efficiency is a number.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"La velocità è una sensazione. L'efficienza è un numero.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S04","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":4,"global_order":289,"speaker":"ARAN","english_text":"Speed is the number that matters to the person who needs it. Efficiency is the number that matters to the person designing the course.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"La velocità è il numero che conta per chi ne ha bisogno. L'efficienza è il numero che conta per chi progetta il corso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S05","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":5,"global_order":290,"speaker":"TOM","english_text":"Then we're not going to agree.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora non ci metteremo d'accordo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S06","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":6,"global_order":291,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"No.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S07","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":7,"global_order":292,"speaker":"TOM","english_text":"Then we'll put it on pause. Like the thirteen weeks.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora la mettiamo in pausa. Come le tredici settimane.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S08","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":8,"global_order":293,"speaker":"ARAN","english_text":"No. Not on pause. The thirteen weeks went on pause because it doesn't matter which of us is right — a hundred hours is a hundred hours, you said so yourself. This one matters. If you build for efficiency and I sell for speed, we're building two different things and calling them one, and we should know that, out loud, every day. Leave it standing.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"No. Non in pausa. Le tredici settimane le abbiamo messe in pausa perché non importa chi di noi due ha ragione — cento ore sono cento ore, l'hai detto tu. Questa conta. Se tu costruisci per l'efficienza e io vendo per la velocità, stiamo costruendo due cose diverse e le chiamiamo una, e dobbiamo saperlo, ad alta voce, ogni giorno. Lasciamolo in piedi.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S09","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":9,"global_order":294,"speaker":"TOM","english_text":"Good. Leave it standing. I build for efficiency, you sell it for speed, and the learners tell us which of us was right.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Bene. Lasciamolo in piedi. Io costruisco per l'efficienza, tu lo vendi per la velocità, e chi impara ci dirà chi di noi due aveva ragione.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S10","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":10,"global_order":295,"speaker":"ARAN","english_text":"Standing. Next thing.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"In piedi. Prossima cosa.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S11","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":11,"global_order":296,"speaker":"TOM","english_text":"Next thing. Two days on molecular physics. In Hong Kong. Coming?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Prossima cosa. Due giorni di fisica molecolare. A Hong Kong. Vieni?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S12","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":12,"global_order":297,"speaker":"ARAN","english_text":"From anyone else: no. Sorry — molecular physics, not my thing. From you: yes. I've already said yes. Because you wouldn't have asked.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Da chiunque altro: no. Scusa — la fisica molecolare non fa per me. Da te: sì. Ho già detto di sì. Perché tu non me l'avresti chiesto.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S13","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":13,"global_order":298,"speaker":"TOM","english_text":"I almost don't have to explain anything.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Quasi non devo nemmeno spiegare niente.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S14","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":14,"global_order":299,"speaker":"ARAN","english_text":"You don't. What you're giving me isn't a recommendation, it's a guarantee — yours — and that's what a tribe is. A dozen people who know what you'd find interesting, and bring it to you. The other version of that filter is somebody in California writing an algorithm, and that filter is driving all of us towards people who already agree with us. Your version is the antidote. We just spent ten minutes not agreeing, and I'm still coming to Hong Kong.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non devi. Quello che mi dai non è un consiglio, è una garanzia — la tua — ed è questo una tribù. Una dozzina di persone che sanno cosa troveresti interessante, e te lo portano. L'altra versione di quel filtro è qualcuno in California che scrive un algoritmo, e quel filtro ci sta spingendo tutti verso chi è già d'accordo con noi. La tua versione è l'antidoto. Abbiamo appena passato dieci minuti a non essere d'accordo, e a Hong Kong ci vengo lo stesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S15","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":15,"global_order":300,"speaker":"TOM","english_text":"So — Breton, for a weekend?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Allora — bretone, per un fine settimana?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S16","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":16,"global_order":301,"speaker":"ARAN","english_text":"Why not.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Perché no.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S17","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":17,"global_order":302,"speaker":"TOM","english_text":"Right. That's the hour. Let's stop there.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Bene. È passata l'ora. Fermiamoci qui.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S18","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":18,"global_order":303,"speaker":"ARAN","english_text":"One thing. Somebody at Cardiff: the routes to four thousand words are all different. After four thousand, they're all the same.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Una cosa. Uno a Cardiff: le strade per arrivare a quattromila parole sono tutte diverse. Dopo le quattromila, sono tutte uguali.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S19","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":19,"global_order":304,"speaker":"TOM","english_text":"Interesting. …No. Hang on. Four thousand?","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Interessante. …No. Aspetta. Quattromila?","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S20","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":20,"global_order":305,"speaker":"ARAN","english_text":"Four thousand. Below it, every method looks different — whatever road you took. Above it, nobody can tell which one you used; from there it's only how often you use the language. So the whole argument we've been having is about the road to four thousand, and after that the road doesn't exist. Efficiency, speed — after four thousand, nobody can tell.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Quattromila. Sotto, ogni metodo sembra diverso — qualunque strada tu abbia preso. Sopra, nessuno sa dire quale hai usato; da lì in poi conta solo quanto spesso usi la lingua. Quindi tutta la discussione che stiamo facendo è sulla strada fino a quattromila, e dopo la strada non esiste. Efficienza, velocità — dopo le quattromila, nessuno lo sa dire.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S21","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":21,"global_order":306,"speaker":"TOM","english_text":"We're not stopping.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Non ci fermiamo.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S22","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":22,"global_order":307,"speaker":"ARAN","english_text":"You said the hour.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Hai detto l'ora.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S23","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":23,"global_order":308,"speaker":"TOM","english_text":"I said the hour. Stop the recording, start another one. Part two. Now.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Ho detto l'ora. Ferma la registrazione, fanne partire un'altra. Parte due. Adesso.","target_lang":"ita","attach_sentence_number":null}, 
 {"id":"method-pod-chapters:SC12-S24","pod_slug":"method-pod-chapters","scene_number":12,"scene_label":"Chapter 12","scene_title":"Efficienza e velocità","scene_subtitle":"what we are building for, and the disagreement stands","difficulty":null,"sentence_number":24,"global_order":309,"speaker":"ARAN","english_text":"Now.","author_notes":null,"created_at":"2026-08-30T19:35:31.97371+00:00","updated_at":"2026-08-30T19:35:31.97371+00:00","variant_key":null,"target_text":"Adesso.","target_lang":"ita","attach_sentence_number":null}]
$m$);
